head.b:skin:
:root{
  --bg:#000d08;--bg2:#00150d;--panel:#031b12;--panel2:#06251a;
  --line:rgba(48,255,145,.20);--line2:rgba(48,255,145,.32);
  --green:#28f58c;--green2:#7dffb7;--gold:#ffd65d;
  --text:#f5fff8;--muted:#8fa79a;--danger:#ff727b;
  --nav:74px;--r:17px;--rs:12px;
  font-family:Inter,system-ui,-apple-system,BlinkMacSystemFont,"Segoe UI",sans-serif
}
*{box-sizing:border-box}
img,svg{max-width:100%}
img{user-select:none;-webkit-user-drag:none}
html,body{width:100%;overflow-x:hidden}
html{margin:0;min-height:100%;background:var(--bg)}
body{margin:0;min-height:100vh;overflow-x:hidden;padding-bottom:calc(var(--nav) + env(safe-area-inset-bottom));background:radial-gradient(circle at 50% -8%,rgba(0,255,128,.09),transparent 28%),linear-gradient(180deg,#00140c,#000d08 44%,#000b07);color:var(--text);-webkit-tap-highlight-color:transparent}
button,input,select,textarea{font:inherit}
button,label{-webkit-tap-highlight-color:transparent}
button{cursor:pointer}
label{cursor:pointer}
input,select,textarea{outline:none}
.route-radio,.drawer-radio,.modal-radio{position:fixed;left:-9999px;opacity:0;pointer-events:none}
.app{width:100%;max-width:520px;min-height:100vh;margin:0 auto;position:relative;overflow-x:clip}
.grow{flex:1;min-width:0}
.hidden{display:none!important}
.topbar{position:sticky;top:0;z-index:60;height:64px;display:flex;align-items:center;gap:7px;padding:8px 10px;background:rgba(0,14,9,.985);border-bottom:1px solid rgba(48,255,145,.15);box-shadow:0 8px 24px rgba(0,0,0,.18);overflow:hidden}
.topbar>*{min-width:0}
.icon{width:38px;height:38px;flex:0 0 38px;display:grid;place-items:center;border:1px solid var(--line2);border-radius:11px;background:linear-gradient(180deg,#06251a,#00160e);color:var(--text)}
.icon svg{width:21px;height:21px}
.brand{display:flex;align-items:center;gap:7px;min-width:0;flex:0 1 auto;overflow:hidden}


.guest-actions{display:flex;gap:5px;align-items:center;flex:0 0 auto;min-width:0}
.member-actions{display:none;gap:5px;align-items:center}
body.is-member .guest-actions{display:none}
body.is-member .member-actions{display:flex}
.top-pill{height:38px;display:flex;align-items:center;justify-content:center;padding:0 10px;border:1px solid var(--line2);border-radius:11px;font-size:10px;font-weight:950;white-space:nowrap}
.top-pill.login{background:#021a11;color:#f4fff8}
.top-pill.register{background:linear-gradient(180deg,#48ffa1,#12d979);color:#00180c}
.balance-pill{height:38px;max-width:126px;display:flex;align-items:center;gap:7px;padding:0 10px;border:1px solid var(--line2);border-radius:11px;background:#032017;font-size:9px;font-weight:900;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.coin{width:15px;height:15px;display:grid;place-items:center;flex:0 0 15px;color:var(--gold)}
.coin svg{width:15px;height:15px;display:block;fill:none;stroke:currentColor;stroke-width:1.8;stroke-linecap:round;stroke-linejoin:round}
.content{padding:10px 10px 12px}
.view{display:none;min-height:calc(100vh - 150px);padding-bottom:10px}
#route-bank:checked ~ .app .view[data-view='bank']{display:block}
#route-deposit:checked ~ .app .view[data-view='deposit']{display:block}
#route-edit-profile:checked ~ .app .view[data-view='edit-profile']{display:block}
#route-faq:checked ~ .app .view[data-view='faq']{display:block}
#route-games:checked ~ .app .view[data-view='games']{display:block}
#route-history:checked ~ .app .view[data-view='history']{display:block}
#route-home:checked ~ .app .view[data-view='home']{display:block}
#route-privacy:checked ~ .app .view[data-view='privacy']{display:block}
#route-profile:checked ~ .app .view[data-view='profile']{display:block}
#route-promo:checked ~ .app .view[data-view='promo']{display:block}
#route-security:checked ~ .app .view[data-view='security']{display:block}
#route-settings:checked ~ .app .view[data-view='settings']{display:block}
#route-support:checked ~ .app .view[data-view='support']{display:block}
#route-terms:checked ~ .app .view[data-view='terms']{display:block}
#route-wallet:checked ~ .app .view[data-view='wallet']{display:block}
#route-withdraw:checked ~ .app .view[data-view='withdraw']{display:block}
.guest-route{display:flex!important}
.member-route{display:none!important}
body.is-member .guest-route{display:none!important}
body.is-member .member-route{display:flex!important}
/* V57: prevent guest/member flash while Firebase restores persisted auth. */
body.auth-booting .guest-route,body.auth-booting .member-route{visibility:hidden!important;pointer-events:none!important}
.member-block{display:none!important}
body.is-member .member-block{display:block!important}
body.is-member .guest-block{display:none!important}
/* V72: ordered banners, next slide moves to the right. */
.hero{position:relative;width:100%;overflow:hidden;border:1px solid rgba(77,255,164,.24);border-radius:16px;background:#00180f;box-shadow:0 6px 18px rgba(0,0,0,.16)}
.hero-viewport{position:relative;aspect-ratio:8/3;overflow:hidden;touch-action:pan-y pinch-zoom;background:#00180f}
.hero-slide{position:absolute;inset:0;transform:translateX(0);transition:transform 420ms cubic-bezier(.22,.61,.36,1)}
.hero-slide[hidden]{display:none!important}
.hero-slide img{display:block;width:100%;height:100%;object-fit:contain;object-position:center;user-select:none;-webkit-user-drag:none}
.hero-message{position:absolute;inset:0;display:grid;place-items:center;padding:12px;color:#c8edda;font-size:11px;text-align:center}
.hero-message[hidden]{display:none}
@media(prefers-reduced-motion:reduce){.hero-slide{transition:none}}
.section{margin-top:20px}
.section-head{display:flex;align-items:center;gap:9px;min-height:40px;margin:0 1px 10px}
.section-icon{width:31px;height:31px;flex:0 0 31px;display:grid;place-items:center;border:1px solid rgba(91,255,168,.22);border-radius:10px;background:linear-gradient(145deg,rgba(34,245,139,.14),rgba(2,33,21,.88));color:#55ffa7;box-shadow:inset 0 1px rgba(255,255,255,.05),0 7px 17px rgba(0,0,0,.16)}
.section-icon svg{width:17px;height:17px;fill:none;stroke:currentColor;stroke-linecap:round;stroke-linejoin:round;stroke-width:1.8}
.section-icon.hot{color:#ffd966;border-color:rgba(255,217,102,.22);background:linear-gradient(145deg,rgba(255,209,76,.12),rgba(36,27,3,.72))}
.section-icon.latest{color:#58ffac}
.section-icon.all{color:#7de6ff;border-color:rgba(125,230,255,.20);background:linear-gradient(145deg,rgba(65,191,224,.12),rgba(2,28,34,.76))}
.section-head h2{margin:0;color:#f6fff9;font-size:17px;line-height:1.05;letter-spacing:-.25px;font-weight:950}
.section-head p{margin:3px 0 0;color:#789084;font-size:8.5px;line-height:1.25;font-weight:650}
.more{flex:0 0 auto;display:inline-flex;align-items:center;justify-content:center;min-height:29px;padding:6px 10px;border:1px solid rgba(62,255,151,.20);border-radius:10px;background:linear-gradient(180deg,#06271b,#02170f);color:#cffff0;font-size:8.4px;font-weight:900;white-space:nowrap;box-shadow:inset 0 1px rgba(255,255,255,.035)}
.providers{display:flex;gap:7px;overflow-x:auto;overflow-y:hidden;padding:2px 10px 4px 1px;scroll-snap-type:x proximity;scrollbar-width:none;-webkit-overflow-scrolling:touch}
.providers::-webkit-scrollbar{display:none}
.provider-card{flex:0 0 clamp(80px,23.2vw,96px);height:64px;overflow:hidden;border:1px solid rgba(48,255,145,.22);border-radius:12px;background:#031d14;scroll-snap-align:start}
.provider-card:first-child{border-color:#40f69b;box-shadow:0 0 13px rgba(38,245,139,.18)}
.provider-card img{width:100%;height:100%;display:block;object-fit:cover}
.slot-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:8px;width:100%;align-items:start}
.slot-card{position:relative;isolation:isolate;min-width:0;overflow:hidden;border:1px solid rgba(63,255,154,.18);border-radius:15px;background:linear-gradient(180deg,#06261b,#02150e);box-shadow:0 9px 23px rgba(0,0,0,.22),inset 0 1px rgba(255,255,255,.025);transition:transform .16s ease,border-color .16s ease,box-shadow .16s ease;transform:translateZ(0)}
.slot-card:active{transform:scale(.985);border-color:rgba(76,255,163,.38);box-shadow:0 5px 15px rgba(0,0,0,.22)}
.slot-art{position:relative;width:100%;aspect-ratio:4/5;overflow:hidden;background:linear-gradient(145deg,#073021,#02140d)}
.slot-art:after{content:"";position:absolute;z-index:1;left:0;right:0;bottom:0;height:34%;pointer-events:none;background:linear-gradient(180deg,transparent,rgba(0,13,8,.74))}
.slot-art img{position:relative;z-index:0;width:100%;height:100%;display:block;object-fit:cover;object-position:center center;transition:transform .24s ease}
.slot-card:active .slot-art img{transform:scale(1.025)}
.slot-art>img~img{display:none!important}
.rtp-badge{position:absolute;left:6px;bottom:6px;top:auto;z-index:3;display:inline-flex;align-items:center;justify-content:center;max-width:calc(100% - 12px);padding:4px 6px;border:1px solid rgba(78,255,158,.42);border-radius:7px;background:rgba(0,29,18,.86);color:#dbffea;font-size:6.6px;line-height:1;font-weight:950;letter-spacing:.08px;white-space:nowrap;box-shadow:0 2px 8px rgba(0,0,0,.30);backdrop-filter:none;}
.slot-body{padding:8px 7px 7px}
.slot-body b{display:block;min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;color:#f6fff9;font-size:10px;line-height:1.25;font-weight:900;letter-spacing:-.08px}
.slot-body small{display:block;min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;margin-top:2px;color:#789084;font-size:7.4px;line-height:1.2}
.play-btn{display:flex;align-items:center;justify-content:center;width:100%;min-height:31px;margin-top:7px;padding:7px 3px;border:1px solid rgba(140,255,195,.30);border-radius:9px;background:linear-gradient(180deg,#5dffae,#18d97d);box-shadow:inset 0 1px rgba(255,255,255,.34),0 5px 12px rgba(11,173,91,.10);color:#00170c;font-size:9px;line-height:1;font-weight:1000;letter-spacing:.06px}
.view[data-view='home']{padding-bottom:calc(104px + env(safe-area-inset-bottom))}
.view[data-view='home'] .slot-body>small{display:none!important}
.view[data-view='home'] .slot-body>b{display:block!important}
.view[data-view='home']
.view[data-view='home'] .play-btn{margin-top:6px}
.page-head{display:flex;align-items:center;gap:9px;min-height:46px;margin:2px 0 11px;padding-top:4px}
.page-head h1{margin:0;font-size:20px;letter-spacing:-.25px}
.back{width:38px;height:38px;display:grid;place-items:center;border:1px solid var(--line);border-radius:11px;background:#031d14;color:#f0fff5;font-size:22px}
.panel,.section-card{border:1px solid var(--line);border-radius:17px;background:linear-gradient(150deg,#05251a,#00160e);box-shadow:0 10px 23px rgba(0,0,0,.12)}
.panel{padding:15px;margin-bottom:10px}
.panel h2,.panel h3,.section-card h3{margin:0 0 5px}
.panel p,.section-card>p{margin:0;color:var(--muted);font-size:9px;line-height:1.5}
.section-card{padding:15px}
.screen-shell{display:grid;gap:10px}
.screen-hero,.page-hero{position:relative;overflow:hidden;padding:17px;border:1px solid rgba(48,255,145,.23);border-radius:18px;background:radial-gradient(circle at 88% 14%,rgba(255,215,91,.15),transparent 23%),radial-gradient(circle at 8% 105%,rgba(39,245,139,.11),transparent 30%),linear-gradient(145deg,#07331f,#00150d 72%);box-shadow:0 13px 28px rgba(0,0,0,.18)}
.screen-hero .overline,.page-kicker{color:var(--green2);font-size:8px;font-weight:1000;letter-spacing:1.6px;text-transform:uppercase}
.screen-hero h2,.page-hero h2{margin:6px 0 5px;font-size:21px;line-height:1.08}
.screen-hero p,.page-hero p{max-width:88%;margin:0;color:#9bb1a4;font-size:10px;line-height:1.5}
.screen-hero .hero-row,.page-hero-actions{display:flex;gap:6px;flex-wrap:wrap;margin-top:12px}
.soft-chip,.hero-chip,.profile-chip,.wallet-status{display:inline-flex;align-items:center;gap:5px;padding:6px 8px;border:1px solid rgba(48,255,145,.18);border-radius:999px;background:rgba(0,0,0,.16);color:#d9ffe7;font-size:8px;font-weight:900}
.field{margin:11px 0}
.field label{display:block;margin-bottom:6px;color:#b7cabf;font-size:9px;font-weight:850}
.field input,.field select,.field textarea{width:100%;padding:12px;border:1px solid rgba(48,255,145,.17);border-radius:12px;background:#00160e;color:white}
.field input:focus,.field select:focus,.field textarea:focus{border-color:#33ed8c;box-shadow:0 0 0 3px rgba(35,245,139,.07)}
.field textarea{min-height:92px;resize:vertical}
.form-pro{display:grid;gap:10px}
.form-pro .field{margin:0}
.input-hint{margin-top:4px;color:#6f8778;font-size:7.5px;line-height:1.35}
.btn{min-height:43px;display:flex;align-items:center;justify-content:center;width:100%;padding:11px;border:0;border-radius:12px;font-weight:950;text-align:center}
.btn.primary{background:linear-gradient(180deg,#46ffa2,#10d776);color:#00170c;box-shadow:0 0 18px rgba(35,245,139,.10)}
.btn.secondary{border:1px solid var(--line);background:#032017;color:white}
.cta-pro{display:flex;gap:8px;margin-top:3px}
.cta-pro .btn{flex:1}
.list,.menu-list{overflow:hidden;border:1px solid rgba(48,255,145,.15);border-radius:14px;background:#00180f}
.row,.menu-line{display:flex;align-items:center;gap:10px;padding:12px;border:0;border-bottom:1px solid rgba(255,255,255,.045);background:transparent;color:#effff4;text-align:left}
.row:last-child,.menu-line:last-child{border-bottom:0}
.row b,.menu-line b{display:block;font-size:11px}
.row small,.menu-line small{display:block;margin-top:2px;color:#82998b;font-size:8px;line-height:1.35}
.menu-line{width:100%}
.menu-line .menu-ico{width:34px;height:34px;flex:0 0 34px;display:grid;place-items:center;border:1px solid rgba(34,245,137,.13);border-radius:10px;background:rgba(34,245,137,.075);font-size:15px}
.menu-line .copy{flex:1;min-width:0}
.menu-line .arr{color:#7b9385;font-size:16px}
.metric-row{display:grid;grid-template-columns:repeat(2,1fr);gap:8px}
.metric-box{min-height:77px;padding:13px;border:1px solid rgba(48,255,145,.15);border-radius:14px;background:#031d14}
.metric-box small{display:block;color:#82998c;font-size:8px}
.metric-box strong{display:block;margin-top:4px;font-size:16px}
.metric-box .meta{margin-top:3px;color:#64d993;font-size:7px}
.status-line{min-height:45px;display:flex;align-items:center;gap:8px;padding:10px;border:1px solid rgba(48,255,145,.13);border-radius:12px;background:rgba(31,245,139,.035)}
.status-dot{width:7px;height:7px;flex:0 0 7px;border-radius:50%;background:#31ed8e;box-shadow:0 0 10px rgba(49,237,142,.3)}
.status-line b{font-size:9px}
.status-line span{color:#809689;font-size:8px}
.wallet-card{padding:19px;border:1px solid rgba(48,255,145,.26);border-radius:18px;background:radial-gradient(circle at 85% 10%,rgba(255,214,93,.11),transparent 24%),linear-gradient(145deg,#073522,#00170f)}
.wallet-card small,.balance-label{color:var(--muted);font-size:10px}
.wallet-card strong{display:block;margin:4px 0 10px;font-size:27px}
.wallet-meta{display:flex;gap:7px;align-items:center;margin-bottom:12px}
.wallet-secure{color:#768e80;font-size:8px}
.wallet-actions{display:grid;grid-template-columns:repeat(3,1fr);gap:7px}
.wallet-actions label{padding:9px 3px;border:1px solid var(--line);border-radius:10px;background:#032017;text-align:center;font-size:8px;font-weight:900}
.wallet-pro-shell{display:grid;gap:11px}
.wallet-pro-balance{position:relative;overflow:hidden;padding:17px;border:1px solid rgba(52,255,151,.30);border-radius:19px;background:radial-gradient(circle at 90% 4%,rgba(65,255,155,.17),transparent 28%),radial-gradient(circle at 18% 110%,rgba(255,210,77,.08),transparent 32%),linear-gradient(145deg,#073823,#00170f 72%);box-shadow:0 16px 34px rgba(0,0,0,.22)}
.wallet-pro-balance:after{content:'';position:absolute;right:-34px;top:-55px;width:150px;height:150px;border-radius:50%;border:1px solid rgba(73,255,165,.09);box-shadow:0 0 50px rgba(35,255,142,.08);pointer-events:none}
.wallet-pro-top{display:flex;align-items:center;justify-content:space-between;gap:10px}
.wallet-pro-label{display:flex;align-items:center;gap:8px;font-size:10px;font-weight:900;color:#eafff1}
.wallet-pro-label svg{width:17px;height:17px;fill:none;stroke:#53ffa8;stroke-width:1.8}
.wallet-pro-balance strong{display:block;margin:7px 0 4px;font-size:30px;letter-spacing:-.7px;color:#f4fff8;text-shadow:0 0 20px rgba(74,255,164,.11)}
.wallet-pro-caption{color:#8da799;font-size:9px}
.wallet-pro-meta{display:flex;align-items:center;gap:6px;flex-wrap:wrap;margin-top:12px}
.wallet-pro-chip{padding:5px 8px;border:1px solid rgba(71,255,162,.16);border-radius:999px;background:rgba(35,255,143,.05);color:#9fb9aa;font-size:7px;font-weight:800}
.wallet-pro-status{display:inline-flex;align-items:center;gap:5px;padding:5px 8px;border:1px solid rgba(71,255,162,.19);border-radius:999px;background:rgba(35,255,143,.07);font-size:7px;font-weight:900;color:#5dffad}
.wallet-pro-status:before{content:'';width:5px;height:5px;border-radius:50%;background:#45ffa2;box-shadow:0 0 8px rgba(69,255,162,.8)}
.wallet-pro-actions{display:grid;grid-template-columns:1fr 1fr;gap:9px}
.wallet-pro-action{min-height:74px;display:flex;align-items:center;gap:10px;padding:12px;border:1px solid rgba(58,255,155,.22);border-radius:17px;background:linear-gradient(145deg,#052a1c,#00160f);box-shadow:0 10px 22px rgba(0,0,0,.15);cursor:pointer}
.wallet-pro-action.deposit{border-color:rgba(52,255,151,.50);background:linear-gradient(145deg,#22ef8a,#0cc66f);color:#00160d;box-shadow:0 12px 28px rgba(27,239,135,.18)}
.wallet-pro-action.withdraw{background:linear-gradient(145deg,#073823,#00180f)}
.wallet-pro-action-ico{width:39px;height:39px;display:grid;place-items:center;flex:0 0 auto;border-radius:13px;background:rgba(0,20,13,.34);border:1px solid rgba(255,255,255,.06)}
.wallet-pro-action.deposit .wallet-pro-action-ico{background:rgba(0,35,21,.42);border-color:rgba(0,0,0,.08)}
.wallet-pro-action-ico svg{width:22px;height:22px;fill:none;stroke:currentColor;stroke-width:2;stroke-linecap:round;stroke-linejoin:round}
.wallet-pro-action-copy{min-width:0;flex:1}
.wallet-pro-action-copy b{display:block;font-size:11px;line-height:1.1}
.wallet-pro-action-copy small{display:block;margin-top:3px;color:#89a596;font-size:8px}
.wallet-pro-action.deposit .wallet-pro-action-copy small{color:#064a2c}
.wallet-pro-action-arr{font-size:17px;opacity:.78}
.wallet-pro-panel{padding:13px;border:1px solid rgba(54,255,153,.16);border-radius:17px;background:linear-gradient(145deg,#031f15,#00140d);box-shadow:0 10px 24px rgba(0,0,0,.12)}
.wallet-pro-panel-head{display:flex;align-items:center;justify-content:space-between;gap:10px;margin-bottom:9px}
.wallet-pro-panel-title{display:flex;align-items:center;gap:8px}
.wallet-pro-panel-icon{width:31px;height:31px;display:grid;place-items:center;border:1px solid rgba(61,255,158,.20);border-radius:10px;background:rgba(35,255,143,.055);color:#54ffa8}
.wallet-pro-panel-icon svg{width:17px;height:17px;fill:none;stroke:currentColor;stroke-width:1.8;stroke-linecap:round;stroke-linejoin:round}
.wallet-pro-panel-title b{display:block;font-size:10px}
.wallet-pro-panel-title small{display:block;margin-top:2px;color:#7e998a;font-size:7px}
.wallet-pro-link{padding:6px 9px;border:1px solid rgba(64,255,160,.16);border-radius:999px;color:#9eb7a9;font-size:7px;font-weight:900}
.wallet-bank-summary{display:flex;align-items:center;gap:10px;padding:10px;border:1px solid rgba(60,255,157,.10);border-radius:13px;background:#00170f}
.wallet-bank-logo{width:36px;height:36px;display:grid;place-items:center;border-radius:11px;background:rgba(35,255,143,.06);border:1px solid rgba(65,255,162,.14);color:#55ffa9}
.wallet-bank-logo svg{width:19px;height:19px;fill:none;stroke:currentColor;stroke-width:1.8}
.wallet-bank-copy{min-width:0;flex:1}
.wallet-bank-copy b{display:block;font-size:10px}
.wallet-bank-copy span{display:block;margin-top:2px;color:#9bb2a5;font-size:9px;font-weight:800}
.wallet-bank-copy small{display:block;margin-top:2px;color:#708b7c;font-size:7px}
.wallet-bank-badge{padding:5px 7px;border-radius:999px;background:rgba(38,255,144,.09);border:1px solid rgba(56,255,154,.16);color:#58ffac;font-size:7px;font-weight:900}
.wallet-recent-list{display:grid;gap:6px}
.wallet-recent-row{min-height:49px;display:flex;align-items:center;gap:9px;padding:8px 9px;border:1px solid rgba(59,255,156,.09);border-radius:12px;background:#00170f}
.wallet-recent-ico{width:29px;height:29px;display:grid;place-items:center;border-radius:10px;background:rgba(35,255,143,.06);color:#56ffab;font-size:14px;font-weight:900}
