.account-inline-status{display:flex;align-items:center;gap:6px;padding:8px 10px;border:1px solid rgba(61,255,158,.10);border-radius:12px;background:rgba(35,255,143,.035);color:#7f9a8b;font-size:7px;line-height:1.45}
.account-inline-status:before{content:'';width:6px;height:6px;flex:0 0 6px;border-radius:50%;background:#45ffa2;box-shadow:0 0 7px rgba(69,255,162,.65)}
.account-person-card{display:flex;align-items:center;gap:10px;padding:11px;border:1px solid rgba(60,255,157,.10);border-radius:14px;background:#00170f}
.account-person-avatar{width:42px;height:42px;display:grid;place-items:center;flex:0 0 42px;border-radius:13px;background:linear-gradient(145deg,#24eb89,#0abf69);color:#00160d;font-size:16px;font-weight:1000}
.account-person-copy{min-width:0;flex:1}
.account-person-copy b{display:block;font-size:9px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.account-person-copy span{display:block;margin-top:2px;color:#8fa89a;font-size:7.5px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.account-person-copy small{display:block;margin-top:2px;color:#6d8879;font-size:6.5px}
.saved-account-card{display:flex;align-items:center;gap:10px;padding:12px;border:1px solid rgba(62,255,158,.14);border-radius:15px;background:#00170f}
.saved-account-icon{width:40px;height:40px;display:grid;place-items:center;flex:0 0 40px;border:1px solid rgba(65,255,160,.14);border-radius:12px;background:rgba(35,255,143,.055);color:#58ffac}
.saved-account-icon svg{width:19px;height:19px;fill:none;stroke:currentColor;stroke-width:1.8}
.saved-account-copy{min-width:0;flex:1}
.saved-account-copy b{display:block;font-size:9px}
.saved-account-copy span{display:block;margin-top:2px;color:#a6bbae;font-size:8px;font-weight:900}
.saved-account-copy small{display:block;margin-top:2px;color:#6f8b7c;font-size:6.5px}
.saved-account-badge{padding:5px 8px;border:1px solid rgba(67,255,161,.16);border-radius:999px;background:rgba(35,255,143,.055);color:#5dffad;font-size:6.5px;font-weight:900}
.security-grid{display:grid;gap:8px}
.security-item{display:flex;align-items:center;gap:10px;padding:11px;border:1px solid rgba(59,255,156,.10);border-radius:14px;background:#00170f}
.security-icon{width:35px;height:35px;display:grid;place-items:center;flex:0 0 35px;border:1px solid rgba(64,255,160,.13);border-radius:11px;background:rgba(35,255,143,.045);color:#58ffac}
.security-icon svg{width:18px;height:18px;fill:none;stroke:currentColor;stroke-width:1.8;stroke-linecap:round;stroke-linejoin:round}
.security-copy{min-width:0;flex:1}
.security-copy b{display:block;font-size:9px}
.security-copy small{display:block;margin-top:2px;color:#718c7d;font-size:7px}
.security-badge{padding:5px 8px;border:1px solid rgba(64,255,160,.14);border-radius:999px;color:#9eb8aa;font-size:6.5px;font-weight:900}
.security-badge.ok{color:#5dffad;background:rgba(35,255,143,.05)}
.security-action{border:0;background:transparent;color:#58ffac;font-size:7px;font-weight:900;padding:6px}
.transaction-toolbar{display:flex;align-items:center;justify-content:space-between;gap:8px;flex-wrap:wrap}
.transaction-filter{display:flex;gap:6px;flex-wrap:wrap}
.transaction-filter-btn{padding:6px 9px;border:1px solid rgba(61,255,158,.11);border-radius:999px;background:#00170f;color:#829d8e;font-size:6.8px;font-weight:900}
.transaction-filter-btn.active{border-color:rgba(64,255,160,.30);background:rgba(35,255,143,.07);color:#5dffad}
.transaction-count{color:#718c7d;font-size:7px}
.transaction-modern-list{display:grid;gap:7px;margin-top:9px}
.transaction-modern-row{display:flex;align-items:center;gap:10px;padding:10px;border:1px solid rgba(59,255,156,.09);border-radius:13px;background:#00170f}
.transaction-modern-icon{width:34px;height:34px;display:grid;place-items:center;flex:0 0 34px;border-radius:11px;background:rgba(35,255,143,.055);color:#58ffac;font-size:14px;font-weight:1000}
.transaction-modern-icon.debit{background:rgba(255,88,99,.06);color:#ff737d}
.transaction-modern-copy{min-width:0;flex:1}
.transaction-modern-copy b{display:block;font-size:9px}
.transaction-modern-copy small{display:block;margin-top:2px;color:#708b7c;font-size:6.8px}
.transaction-modern-amount{text-align:right}
.transaction-modern-amount b{display:block;color:#5dffad;font-size:8px}
.transaction-modern-amount b.debit{color:#ff737d}
.transaction-modern-amount small{display:block;margin-top:2px;color:#668173;font-size:6.5px}
.transaction-empty{padding:16px 12px;border:1px dashed rgba(60,255,157,.12);border-radius:13px;text-align:center;color:#789486;font-size:7.5px}
.help-category-grid{display:grid;grid-template-columns:1fr 1fr;gap:8px}
.help-category{min-height:83px;display:flex;flex-direction:column;justify-content:space-between;padding:11px;border:1px solid rgba(59,255,156,.10);border-radius:14px;background:#00170f}
.help-category-icon{width:30px;height:30px;display:grid;place-items:center;border:1px solid rgba(64,255,160,.13);border-radius:10px;background:rgba(35,255,143,.045);color:#58ffac;font-size:12px;font-weight:1000}
.help-category b{display:block;margin-top:8px;font-size:9px}
.help-category small{display:block;margin-top:2px;color:#718c7d;font-size:6.8px;line-height:1.4}
.faq-stack{display:grid;gap:7px}
.faq-modern{border:1px solid rgba(59,255,156,.10);border-radius:13px;background:#00170f;overflow:hidden}
.faq-modern summary{display:flex;align-items:center;justify-content:space-between;gap:8px;list-style:none;padding:11px;color:#eafff2;font-size:8.5px;font-weight:900;cursor:pointer}
.faq-modern summary::-webkit-details-marker{display:none}
.faq-modern summary:after{content:'+';color:#58ffac;font-size:14px}
.faq-modern[open] summary:after{content:'−'}
.faq-modern p{margin:0;padding:0 11px 11px;color:#789486;font-size:7.2px;line-height:1.55}
.settings-premium{display:grid;gap:8px}
.settings-premium-row{display:flex;align-items:center;gap:10px;padding:11px;border:1px solid rgba(59,255,156,.10);border-radius:14px;background:#00170f}
.settings-premium-copy{min-width:0;flex:1}
.settings-premium-copy b{display:block;font-size:9px}
.settings-premium-copy small{display:block;margin-top:2px;color:#718c7d;font-size:6.8px}
.settings-premium-control{min-width:122px;height:38px;border:1px solid rgba(61,255,158,.14);border-radius:11px;background:#001a11;color:#eafff2;padding:0 9px;font-size:8px}
.settings-static{padding:6px 8px;border:1px solid rgba(61,255,158,.10);border-radius:999px;color:#9db6a8;font-size:6.5px;font-weight:900}
@media(max-width:380px){
  .help-category-grid{grid-template-columns:1fr}
  .settings-premium-row{align-items:flex-start;flex-direction:column}
  .settings-premium-control{width:100%}
}







.avatar{width:70px;height:70px;display:grid;place-items:center;margin:0 auto;border-radius:22px;background:linear-gradient(180deg,#4aff9f,#08bd62);color:#00170c;font-size:25px;font-weight:1000}
.profile-shell{padding:17px}
.profile-top{display:flex;align-items:center;gap:12px}
.profile-top .avatar{width:60px;height:60px;flex:0 0 60px;margin:0;border-radius:18px}
.profile-top h2{margin:0 0 3px;font-size:18px}
.profile-top p{margin:0;color:var(--muted);font-size:9px}
.center{text-align:center}
.auth-layout{display:grid;gap:10px}
.auth-cover{position:relative;overflow:hidden;min-height:142px;padding:19px;border:1px solid rgba(48,255,145,.25);border-radius:19px;background:radial-gradient(circle at 87% 17%,rgba(255,213,88,.18),transparent 23%),radial-gradient(circle at 7% 98%,rgba(31,245,139,.16),transparent 31%),linear-gradient(145deg,#093923,#00150d 75%)}
.auth-cover:after{content:"B";position:absolute;right:17px;bottom:-18px;color:rgba(56,255,151,.055);font-size:104px;font-style:italic;font-weight:1000}
.auth-logo{display:flex;align-items:center;gap:9px}

.auth-logo b{font-size:13px;letter-spacing:.45px}
.auth-logo small{display:block;margin-top:2px;color:#93aa9d;font-size:8px}
.auth-cover h2{position:relative;z-index:1;margin:16px 0 5px;font-size:22px;line-height:1.08}
.auth-cover p{position:relative;z-index:1;max-width:82%;margin:0;color:#9db1a5;font-size:9px;line-height:1.5}
.auth-points{display:grid;grid-template-columns:repeat(3,1fr);gap:6px;margin-top:12px}
.auth-point{padding:7px 5px;border:1px solid rgba(48,255,145,.13);border-radius:10px;background:rgba(0,0,0,.16);color:#cbe8d6;text-align:center;font-size:7px;font-weight:850}
.auth-form-card{padding:16px;border:1px solid rgba(48,255,145,.18);border-radius:18px;background:linear-gradient(150deg,#052319,#00160e)}
.auth-form-card h3{margin:0 0 3px;font-size:15px}
.auth-form-card .sub{margin-bottom:13px;color:#81998b;font-size:8px}
.auth-divider{display:flex;align-items:center;gap:8px;margin:11px 0;color:#657d6f;font-size:7px}
.auth-divider:before,.auth-divider:after{content:"";height:1px;flex:1;background:rgba(255,255,255,.06)}
.auth-footer{margin-top:11px;color:#7e9587;text-align:center;font-size:8px}
.auth-footer label,.auth-footer button{border:0;background:none;color:#63f7a3;font-weight:900}
/* ===== V19 MEMBER PROMO + AUTH — FINAL CLEAN IMPLEMENTATION ===== */
.promo-filter-state,.promo-detail-state,.auth-state{position:fixed!important;left:-9999px!important;top:-9999px!important;opacity:0!important;pointer-events:none!important}
/* Promo root: langsung kategori + list, tanpa title/back tambahan */
.view[data-view='promo']{padding-top:0!important}
.promo-sync-state{display:none!important}
.promo-tabs{position:sticky;z-index:20;top:64px;display:flex;gap:7px;overflow-x:auto;margin:0 -8px 12px;padding:9px 8px 8px;border-bottom:1px solid rgba(72,255,157,.08);background:linear-gradient(180deg,rgba(0,17,10,.98),rgba(0,13,8,.94));backdrop-filter:none;scrollbar-width:none;-webkit-overflow-scrolling:touch}
.promo-tabs::-webkit-scrollbar{display:none}
.promo-tab{flex:0 0 auto;min-height:37px;display:inline-flex;align-items:center;justify-content:center;padding:0 14px;border:1px solid rgba(76,255,160,.16);border-radius:12px;background:linear-gradient(180deg,#052218,#02160e);color:#829b8c;font-size:9px;font-weight:950;white-space:nowrap;transition:.16s ease}
#promo-filter-all:checked ~ .app .promo-tab[for='promo-filter-all'],
#promo-filter-member:checked ~ .app .promo-tab[for='promo-filter-member'],
#promo-filter-reward:checked ~ .app .promo-tab[for='promo-filter-reward'],
#promo-filter-vip:checked ~ .app .promo-tab[for='promo-filter-vip'],
#promo-filter-tournament:checked ~ .app .promo-tab[for='promo-filter-tournament']{border-color:rgba(82,255,165,.58);background:linear-gradient(180deg,#42f99a,#12cf73);color:#00160b;box-shadow:0 8px 22px rgba(24,222,119,.14)}
#promo-filter-member:checked ~ .app #promoGrid .promo-card:not([data-promo-category='member']),
#promo-filter-reward:checked ~ .app #promoGrid .promo-card:not([data-promo-category='reward']),
#promo-filter-vip:checked ~ .app #promoGrid .promo-card:not([data-promo-category='vip']),
#promo-filter-tournament:checked ~ .app #promoGrid .promo-card:not([data-promo-category='tournament']){display:none!important}
.promo-grid{display:grid;gap:12px;padding-bottom:8px}
.promo-card{position:relative;display:block;overflow:hidden;border:1px solid rgba(71,255,158,.22);border-radius:18px;background:#031a11;box-shadow:0 14px 32px rgba(0,0,0,.25);cursor:pointer;transform:translateZ(0);transition:transform .14s ease,border-color .14s ease,box-shadow .14s ease}
.promo-card:active{transform:scale(.992)}
.promo-card[hidden]{display:none!important}
.promo-banner{position:relative;min-height:164px;overflow:hidden;padding:18px;background:linear-gradient(128deg,#0a4829 0%,#05321e 55%,#01160d 100%)}
.promo-banner:before{content:"";position:absolute;inset:0;background:radial-gradient(circle at 82% 22%,rgba(255,218,91,.28),transparent 25%),radial-gradient(circle at 12% 90%,rgba(61,255,158,.20),transparent 30%),linear-gradient(115deg,rgba(0,0,0,0),rgba(0,0,0,.14));pointer-events:none}
.promo-banner:after{content:"B";position:absolute;right:17px;bottom:-35px;color:rgba(255,255,255,.045);font-size:138px;font-style:italic;font-weight:1000;line-height:1;pointer-events:none}
.promo-card.reward .promo-banner{background:linear-gradient(128deg,#07463e,#092334 60%,#04101a)}
.promo-card.vip .promo-banner{background:linear-gradient(128deg,#483a0d,#201a07 58%,#0f0e05)}
.promo-card.tournament .promo-banner{background:linear-gradient(128deg,#421949,#1d1537 58%,#09101b)}
.promo-kicker{position:relative;z-index:3;display:inline-flex;align-items:center;padding:5px 8px;border:1px solid rgba(255,255,255,.16);border-radius:999px;background:rgba(0,0,0,.22);color:#caffdc;font-size:7px;font-weight:1000;letter-spacing:1px;text-transform:uppercase;backdrop-filter:none;}
.promo-banner h3{position:relative;z-index:3;max-width:69%;margin:12px 0 7px;color:#fff;font-size:24px;line-height:1.02;letter-spacing:-.6px}
.promo-banner p{position:relative;z-index:3;max-width:72%;margin:0;color:#b3ccbe;font-size:9px;line-height:1.52}
.promo-card.vip .promo-banner h3{color:#fff4bc}
.promo-orbit{position:absolute;z-index:2;right:14px;top:18px;width:96px;height:96px;border:1px solid rgba(255,255,255,.13);border-radius:30px;background:linear-gradient(145deg,rgba(255,255,255,.10),rgba(255,255,255,.02));box-shadow:inset 0 1px rgba(255,255,255,.09),0 18px 44px rgba(0,0,0,.24);transform:rotate(10deg)}
.promo-orbit svg{position:absolute;inset:18px;width:60px;height:60px;fill:none;stroke:#e7fff0;stroke-width:1.55;stroke-linecap:round;stroke-linejoin:round;transform:rotate(-10deg)}
.promo-meta{display:flex;align-items:center;gap:9px;padding:10px 11px 11px;background:linear-gradient(180deg,#052219,#02150e)}
.promo-meta-copy{flex:1;min-width:0}
.promo-meta-copy b{display:block;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;font-size:10.5px}
.promo-meta-copy small{display:block;margin-top:3px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;color:#738c7d;font-size:7.7px}
.promo-detail-btn{flex:0 0 auto;min-height:34px;display:inline-flex;align-items:center;justify-content:center;padding:0 12px;border:1px solid rgba(125,255,188,.34);border-radius:10px;background:linear-gradient(180deg,#50ffa8,#14d679);color:#00160b;font-size:8px;font-weight:1000;white-space:nowrap;box-shadow:0 6px 16px rgba(23,219,117,.10)}
.promo-banner-image{position:absolute;inset:0;width:100%;height:100%;object-fit:cover;object-position:center;z-index:0}
.promo-banner.has-image:before{z-index:1;background:linear-gradient(90deg,rgba(0,15,9,.94) 0%,rgba(0,15,9,.66) 52%,rgba(0,15,9,.12) 100%)}
.promo-banner.has-image:after{display:none}
.promo-banner.has-image .promo-kicker,.promo-banner.has-image h3,.promo-banner.has-image p,.promo-banner.has-image .promo-period{position:relative;z-index:2;text-shadow:0 2px 13px rgba(0,0,0,.58)}
.promo-banner.has-image .promo-orbit{display:none}
.promo-period{position:relative;z-index:3;display:inline-flex;margin-top:8px;color:#d4f7e0;font-size:7px;font-weight:850}
/* Shared overlay */
.ui-overlay{position:fixed;z-index:170;inset:0;display:none;align-items:center;justify-content:center;padding:15px;background:rgba(0,8,5,.78);backdrop-filter:none;-webkit-backdrop-filter:none;}
.ui-overlay.open{display:flex}
.ui-sheet{position:relative;width:min(470px,100%);max-height:calc(100dvh - 30px);overflow:auto;border:1px solid rgba(74,255,159,.24);border-radius:22px;background:linear-gradient(160deg,#06251a,#00130c 56%,#000c08);box-shadow:0 28px 90px rgba(0,0,0,.65);animation:modalPop .16s ease-out;-webkit-overflow-scrolling:touch}
@keyframes modalPop{from{opacity:.15;transform:scale(.975) translateY(7px)}to{opacity:1;transform:none}}
.ui-close{position:absolute;z-index:12;right:12px;top:12px;width:38px;height:38px;display:grid;place-items:center;border:1px solid rgba(89,255,167,.20);border-radius:50%;background:rgba(0,18,11,.90);color:#eafff1;font-size:22px;line-height:1;box-shadow:0 8px 20px rgba(0,0,0,.20)}
body.modal-open{overflow:hidden}
/* Static promo detail: radio-driven so Lihat Detail tetap bekerja tanpa JS */
#promo-detail-welcome:checked ~ .app #promoStaticModal,
#promo-detail-cashback:checked ~ .app #promoStaticModal,
#promo-detail-vip:checked ~ .app #promoStaticModal,
#promo-detail-tournament:checked ~ .app #promoStaticModal{display:flex}
#promoStaticModal [data-static-promo-panel]{display:none}
#promo-detail-welcome:checked ~ .app #promoStaticModal [data-static-promo-panel='welcome'],
#promo-detail-cashback:checked ~ .app #promoStaticModal [data-static-promo-panel='cashback'],
#promo-detail-vip:checked ~ .app #promoStaticModal [data-static-promo-panel='vip'],
#promo-detail-tournament:checked ~ .app #promoStaticModal [data-static-promo-panel='tournament']{display:block}
.promo-static-hero{position:relative;overflow:hidden;padding:24px 20px 18px;background:radial-gradient(circle at 86% 18%,rgba(255,214,93,.20),transparent 24%),linear-gradient(145deg,#0a3d26,#00150d 78%)}
.promo-static-hero:after{content:"B";position:absolute;right:17px;bottom:-38px;color:rgba(73,255,163,.05);font-size:145px;font-style:italic;font-weight:1000}
.promo-static-hero .tag{position:relative;z-index:2;display:inline-flex;padding:5px 8px;border:1px solid rgba(89,255,168,.24);border-radius:999px;background:rgba(0,0,0,.18);color:#8affbb;font-size:7px;font-weight:1000;letter-spacing:1px}
.promo-static-hero h2{position:relative;z-index:2;max-width:84%;margin:12px 0 6px;font-size:25px;line-height:1.02;letter-spacing:-.65px}
.promo-static-hero p{position:relative;z-index:2;max-width:86%;margin:0;color:#9bb4a6;font-size:9px;line-height:1.55}
.promo-static-body{padding:15px 16px 8px}
.promo-article-section{padding:12px 0;border-bottom:1px solid rgba(255,255,255,.06)}
.promo-article-section:last-child{border-bottom:0}
.promo-article-section h3{display:flex;align-items:center;gap:7px;margin:0 0 6px;font-size:13px}
.promo-article-section h3:before{content:"";width:7px;height:7px;border:2px solid #42f69a;border-radius:3px;transform:rotate(45deg)}
.promo-article-section p,.promo-article-section li{margin:0;color:#9bb1a4;font-size:9px;line-height:1.62}
.promo-static-note{margin:10px 0 5px;padding:11px;border:1px solid rgba(255,215,91,.16);border-radius:12px;background:rgba(255,215,91,.05);color:#d9ca95;font-size:8px;line-height:1.5}
.promo-static-actions{position:sticky;bottom:0;display:grid;grid-template-columns:1fr 1.45fr;gap:8px;padding:11px 14px calc(11px + env(safe-area-inset-bottom));border-top:1px solid rgba(72,255,158,.12);background:rgba(0,16,10,.96);backdrop-filter:none;}
.promo-static-actions .btn{min-height:44px}
/* Dynamic promo detail dari endpoint backoffice */
.promo-sheet-hero{position:relative;overflow:hidden;padding:24px 20px 18px;background:radial-gradient(circle at 86% 18%,rgba(255,214,93,.20),transparent 24%),linear-gradient(145deg,#0a3d26,#00150d 78%)}
.promo-sheet-hero:after{content:"B";position:absolute;right:17px;bottom:-38px;color:rgba(73,255,163,.05);font-size:145px;font-style:italic;font-weight:1000}
.promo-sheet-badge{position:relative;z-index:2;display:inline-flex;padding:5px 8px;border:1px solid rgba(89,255,168,.24);border-radius:999px;background:rgba(0,0,0,.18);color:#8affbb;font-size:7px;font-weight:1000;letter-spacing:1px}
.promo-sheet-hero h2{position:relative;z-index:2;max-width:84%;margin:12px 0 6px;font-size:25px;line-height:1.02;letter-spacing:-.65px}
.promo-sheet-hero p{position:relative;z-index:2;max-width:86%;margin:0;color:#9bb4a6;font-size:9px;line-height:1.55}
.promo-sheet-body{padding:15px 16px 8px}
.promo-article-note{margin:10px 0 5px;padding:11px;border:1px solid rgba(255,215,91,.16);border-radius:12px;background:rgba(255,215,91,.05);color:#d9ca95;font-size:8px;line-height:1.5}
.promo-sheet-action{position:sticky;bottom:0;display:grid;grid-template-columns:1fr 1.45fr;gap:8px;padding:11px 14px calc(11px + env(safe-area-inset-bottom));border-top:1px solid rgba(72,255,158,.12);background:rgba(0,16,10,.96);backdrop-filter:none;}
.promo-sheet-action .btn{min-height:44px}
/* V23 SIGNATURE AUTH — premium centered member access */
.auth-overlay{z-index:190;align-items:center!important;padding:14px!important;background:rgba(0,9,6,.78)!important;backdrop-filter:none;-webkit-backdrop-filter:none;}
.auth-overlay:before{content:"";position:fixed;inset:0;pointer-events:none;background:radial-gradient(circle at 50% 18%,rgba(45,255,151,.12),transparent 30%),radial-gradient(circle at 86% 76%,rgba(255,214,93,.055),transparent 24%)}
.auth-overlay .ui-sheet{position:relative;width:min(438px,calc(100vw - 24px));max-height:calc(100dvh - 28px);overflow:auto;overscroll-behavior:contain;border:1px solid rgba(92,255,173,.25)!important;border-radius:27px!important;background:radial-gradient(circle at 50% -6%,rgba(52,255,159,.12),transparent 28%),linear-gradient(165deg,#06271b 0%,#00170f 44%,#000d08 100%)!important;box-shadow:0 38px 120px rgba(0,0,0,.78),0 0 0 1px rgba(255,255,255,.025) inset,0 0 54px rgba(26,240,132,.06)!important;transform:scale(.985) translateY(3px)!important;scrollbar-width:none}
.auth-overlay .ui-sheet::-webkit-scrollbar{display:none}
.auth-overlay .ui-sheet:before{content:"";position:absolute;z-index:4;left:62px;right:62px;top:0;height:2px;border-radius:0 0 3px 3px;background:linear-gradient(90deg,transparent,#41f59b 28%,#aaffce 50%,#41f59b 72%,transparent);box-shadow:0 0 18px rgba(59,245,151,.55)}
#auth-login:checked ~ .app #authModal,#auth-register:checked ~ .app #authModal,#auth-forgot:checked ~ .app #authModal{display:flex!important}
#authModal [data-auth-panel]{display:none!important}
#auth-login:checked ~ .app #authModal [data-auth-panel='login'],#auth-register:checked ~ .app #authModal [data-auth-panel='register'],#auth-forgot:checked ~ .app #authModal [data-auth-panel='forgot']{display:block!important}
#authModal .ui-close{position:absolute;z-index:8;right:14px;top:14px;width:38px;height:38px;display:grid;place-items:center;border:1px solid rgba(90,255,170,.17);border-radius:12px;background:rgba(0,24,15,.78);color:#a9c7b6;font-size:22px;line-height:1;backdrop-filter:none;transition:.16s ease}
#authModal .ui-close:active{transform:scale(.94);border-color:rgba(90,255,170,.42);color:#f3fff8}
.auth-modal-top{position:relative;padding:22px 20px 12px;text-align:center;background:transparent}
.auth-modal-brand{display:flex;flex-direction:column;justify-content:center;align-items:center;gap:8px;padding:0 48px}
.auth-brand-logo-wrap{position:relative;display:grid;place-items:center}
.auth-brand-logo-wrap:after{content:"";position:absolute;right:-3px;bottom:2px;width:10px;height:10px;border:2px solid #05251a;border-radius:50%;background:#4cff9f;box-shadow:0 0 12px rgba(76,255,159,.7)}

.auth-brand-copy b{display:block;color:#f6fff9;font-size:14px;letter-spacing:.8px}
.auth-brand-copy small{display:block;margin-top:3px;color:#6e8b7a;font-size:7px;font-weight:800;letter-spacing:.75px;text-transform:uppercase}
.auth-tabs{display:none!important}
.auth-modal-content{padding:11px 20px calc(20px + env(safe-area-inset-bottom))}
.auth-panel{position:relative}
.auth-eyebrow{display:flex;align-items:center;justify-content:center;gap:7px;margin:0 0 7px;color:#6fffb0;font-size:7.2px;font-weight:1000;letter-spacing:1.5px;text-transform:uppercase}
.auth-eyebrow:before,.auth-eyebrow:after{content:"";width:26px;height:1px;background:linear-gradient(90deg,transparent,rgba(94,255,174,.45))}
.auth-eyebrow:after{transform:scaleX(-1)}
.auth-panel h3{margin:0 0 5px;color:#f7fff9;text-align:center;font-size:24px;line-height:1.08;letter-spacing:-.55px;font-weight:1000}
.auth-panel .sub{max-width:335px;margin:0 auto 17px;color:#789384;text-align:center;font-size:9px;line-height:1.52}
.auth-modal-content .field{margin:0 0 11px}
.auth-modal-content .field>label{display:flex;align-items:center;justify-content:space-between;margin:0 2px 6px;color:#c8dbcf;font-size:8.5px;font-weight:950;letter-spacing:.06px}
.auth-field-control{position:relative}
.auth-field-control>svg{position:absolute;z-index:2;left:13px;top:50%;width:17px;height:17px;transform:translateY(-50%);fill:none;stroke:#5cd99b;stroke-width:1.7;stroke-linecap:round;stroke-linejoin:round;pointer-events:none}
.auth-field-control input,.auth-field-control select{width:100%;min-height:50px;padding:0 13px 0 42px!important;border:1px solid rgba(74,255,159,.13);border-radius:14px;outline:none;background:linear-gradient(180deg,#001b11,#00140d);color:#effff5;font:inherit;font-size:11px;box-shadow:inset 0 1px rgba(255,255,255,.012);transition:border-color .16s ease,box-shadow .16s ease,background .16s ease}
.auth-field-control input::placeholder{color:#4f685a}
.auth-field-control input:focus,.auth-field-control select:focus{border-color:rgba(79,255,162,.56);background:#001d12;box-shadow:0 0 0 3px rgba(63,243,147,.07),0 8px 22px rgba(0,0,0,.14)}
.auth-field-control:focus-within>svg{stroke:#81ffbd}
.auth-password-control input{padding-right:52px!important}
.password-eye{position:absolute;z-index:3;right:6px;top:50%;bottom:auto;width:38px;height:38px;transform:translateY(-50%);display:grid;place-items:center;border:1px solid rgba(75,255,159,.12);border-radius:11px;background:#06271b;color:#a9c6b5;cursor:pointer;touch-action:manipulation;-webkit-tap-highlight-color:transparent}
.password-eye svg{position:static!important;width:18px!important;height:18px!important;fill:none!important;stroke:currentColor!important;stroke-width:1.8!important;stroke-linecap:round!important;stroke-linejoin:round!important;pointer-events:none}
.password-eye .eye-off{display:none}
.password-eye[aria-pressed='true'] .eye-open{display:none}
.password-eye[aria-pressed='true'] .eye-off{display:block}
.auth-password-match{display:block;margin-top:5px;color:#6f9180;font-size:7.7px;line-height:1.35}
.auth-password-match.error{color:#ff9d9d}
.auth-password-match.ok{color:#52e99b}
.auth-forgot{display:flex;justify-content:flex-end;margin:-1px 1px 12px}
.auth-link{border:0;background:none;color:#62f7a7;font-size:8.2px;font-weight:950}
.auth-submit{min-height:50px!important;display:flex!important;align-items:center!important;gap:8px!important;border-radius:14px!important;background:linear-gradient(180deg,#5effad,#16d979)!important;box-shadow:inset 0 1px rgba(255,255,255,.42),0 11px 26px rgba(15,202,108,.16)!important;font-size:11.5px!important;letter-spacing:.05px}
.auth-submit svg{width:16px;height:16px;fill:none;stroke:#00170c;stroke-width:2;stroke-linecap:round;stroke-linejoin:round}
.auth-submit:active{transform:translateY(1px)}
.auth-divider{display:flex;align-items:center;gap:10px;margin:14px 0 10px;color:#526d5d;font-size:7px;font-weight:900;text-transform:uppercase;letter-spacing:1px}
.auth-divider:before,.auth-divider:after{content:"";height:1px;flex:1;background:linear-gradient(90deg,transparent,rgba(255,255,255,.08))}.auth-divider:after{transform:scaleX(-1)}
.auth-switchline{display:flex;align-items:center;justify-content:center;gap:5px;margin-top:0;color:#738c7d;text-align:center;font-size:8.2px}
.auth-switchline .switch-btn{min-height:auto;display:inline;border:0;background:none;color:#68ffad;font-size:8.5px;font-weight:1000}
.auth-security-note{display:flex;align-items:flex-start;justify-content:center;gap:7px;margin:14px auto 0;padding-top:12px;border-top:1px solid rgba(255,255,255,.05);color:#587061;font-size:7px;line-height:1.45;text-align:left}
.auth-security-note svg{width:13px;height:13px;flex:0 0 13px;fill:none;stroke:#6e8d7b;stroke-width:1.7;stroke-linecap:round;stroke-linejoin:round}
.auth-modal-content .notice{margin-bottom:10px}
/* V23 registration */
.auth-panel-register h3{margin-bottom:4px}
.auth-register-lead{display:none}
.register-steps{position:relative;display:grid;grid-template-columns:1fr 1fr;gap:7px;margin:0 0 15px;padding:4px;border:1px solid rgba(79,255,162,.09);border-radius:15px;background:#00110b}
.register-step{position:relative;z-index:2;min-height:42px;display:flex;align-items:center;justify-content:center;gap:7px;border:0;border-radius:11px;background:transparent;color:#6d8878;font-size:8.3px;font-weight:950;transition:.16s ease}
.register-step b{width:22px;height:22px;display:grid;place-items:center;border:1px solid rgba(255,255,255,.08);border-radius:8px;background:rgba(255,255,255,.018);font-size:8px}
.register-step.active{background:linear-gradient(180deg,#3cf397,#14d678);color:#00170c;box-shadow:0 8px 22px rgba(22,212,117,.16)}
.register-step.active b{border-color:rgba(0,30,17,.15);background:rgba(0,30,17,.09)}
.register-step-state{position:fixed!important;left:-9999px!important;top:-9999px!important;opacity:0!important;pointer-events:none!important}
.register-page{display:none!important}
#register-step-state-1:checked ~ .register-steps [data-register-step-button='1'],#register-step-state-2:checked ~ .register-steps [data-register-step-button='2']{background:linear-gradient(180deg,#3cf397,#14d678);color:#00170c;box-shadow:0 8px 22px rgba(22,212,117,.16)}
#register-step-state-1:checked ~ .register-steps [data-register-step-button='1'] b,#register-step-state-2:checked ~ .register-steps [data-register-step-button='2'] b{border-color:rgba(0,30,17,.15);background:rgba(0,30,17,.09)}
#register-step-state-1:checked ~ #registerFormModal .register-page[data-register-page='1'],#register-step-state-2:checked ~ #registerFormModal .register-page[data-register-page='2']{display:block!important}
.register-section-label{display:flex;align-items:center;gap:8px;margin:1px 1px 11px;color:#eafff1;font-size:10px;font-weight:950}
.register-section-label:after{content:"";height:1px;flex:1;background:linear-gradient(90deg,rgba(74,255,159,.14),transparent)}
.register-section-label svg{width:16px;height:16px;fill:none;stroke:#57f9a5;stroke-width:1.9;stroke-linecap:round;stroke-linejoin:round}
.auth-form-grid{display:grid;grid-template-columns:1fr 1fr;gap:9px}
.auth-form-grid .field{margin-bottom:0}
.auth-form-grid .field.full{grid-column:1/-1}
.auth-field-hint{display:block;margin:5px 3px 0;color:#536f5e;font-size:6.8px;line-height:1.4}
.register-payment-card{margin-top:1px;padding:12px;border:1px solid rgba(74,255,159,.11);border-radius:16px;background:radial-gradient(circle at 90% 0%,rgba(255,214,93,.055),transparent 27%),linear-gradient(150deg,rgba(10,56,38,.44),rgba(0,18,11,.75));box-shadow:inset 0 1px rgba(255,255,255,.018)}
.register-payment-head{display:flex;align-items:flex-start;gap:10px;margin-bottom:11px}
.register-payment-icon{width:38px;height:38px;display:grid;place-items:center;flex:0 0 38px;border:1px solid rgba(82,255,166,.18);border-radius:12px;background:linear-gradient(145deg,#08301f,#041e15);box-shadow:0 7px 18px rgba(0,0,0,.16)}
.register-payment-icon svg{width:19px;height:19px;fill:none;stroke:#67ffae;stroke-width:1.8;stroke-linecap:round;stroke-linejoin:round}
.register-payment-head b{display:block;color:#f0fff5;font-size:10px}.register-payment-head small{display:block;margin-top:3px;color:#6e8978;font-size:7px;line-height:1.45}
.register-actions{display:grid;grid-template-columns:.8fr 1.45fr;gap:8px;margin-top:13px}.register-actions.one{grid-template-columns:1fr}
.register-back{min-height:48px;border:1px solid rgba(76,255,161,.17);border-radius:13px;background:#031c12;color:#d8f6e4;font-size:9.5px;font-weight:950}
.register-consent{display:flex;align-items:flex-start;gap:8px;margin:11px 2px 0;color:#789183;font-size:7.2px;line-height:1.48}
.register-consent input{width:16px;height:16px;min-height:0;flex:0 0 16px;margin:1px 0 0;accent-color:#31ee8e}.register-consent label{color:#61f7a6;font-weight:900}
.register-safe-note{display:flex;align-items:flex-start;gap:7px;margin:10px 0 0;padding:10px 11px;border:1px solid rgba(255,216,91,.10);border-radius:12px;background:rgba(255,216,91,.035);color:#958d6f;font-size:6.8px;line-height:1.5}.register-safe-note svg{width:13px;height:13px;flex:0 0 13px;fill:none;stroke:#d7c56f;stroke-width:1.8;stroke-linecap:round;stroke-linejoin:round}
@media(max-width:360px){.auth-overlay{padding:8px!important}.auth-overlay .ui-sheet{width:calc(100vw - 16px);border-radius:23px!important}.auth-modal-top{padding-top:18px}.auth-modal-content{padding:9px 14px calc(16px + env(safe-area-inset-bottom))}.auth-panel h3{font-size:22px}.auth-form-grid{grid-template-columns:1fr}.auth-form-grid .field.full{grid-column:auto}.register-step{font-size:7.7px}.register-actions{grid-template-columns:.75fr 1.35fr}}
/* Legacy auth routes tetap ada untuk kompatibilitas, namun tidak dirender sebagai halaman */
#route-login:checked ~ .app .view[data-view='login'],#route-register:checked ~ .app .view[data-view='register'],#route-forgot:checked ~ .app .view[data-view='forgot']{display:none!important}
#route-login:checked ~ .app .view[data-view='home'],#route-register:checked ~ .app .view[data-view='home'],#route-forgot:checked ~ .app .view[data-view='home']{display:block!important}
@media(max-width:350px){
  .promo-tab{padding:0 11px;font-size:8.2px}
  .promo-banner{min-height:154px;padding:16px}
  .promo-banner h3{font-size:21px}
  .promo-orbit{right:10px;width:82px;height:82px}
  .promo-orbit svg{inset:15px;width:52px;height:52px}
  .auth-overlay{padding:9px!important}
  .auth-overlay .ui-sheet{width:calc(100vw - 18px)}
  .auth-modal-content{padding-left:14px;padding-right:14px}
}
.article-shell{display:grid;gap:10px}
.article-cover{padding:19px;border:1px solid rgba(48,255,145,.22);border-radius:19px;background:radial-gradient(circle at 88% 18%,rgba(255,216,91,.17),transparent 24%),linear-gradient(145deg,#07351f,#00160e)}
.article-cover .tag{color:#71ffb0;font-size:8px;font-weight:1000;letter-spacing:1.5px}
.article-cover h1{margin:7px 0;font-size:24px;line-height:1.04}
.article-cover p{margin:0;color:#98aea1;font-size:9px;line-height:1.55}
.article-body{padding:16px;border:1px solid rgba(48,255,145,.16);border-radius:17px;background:#031d14}
.article-body h3{margin:0 0 7px;font-size:14px}
.article-body p,.article-body li{color:#9db1a5;font-size:9px;line-height:1.62}
.article-body ul{margin:7px 0;padding-left:17px}
.article-note{padding:11px;border:1px solid rgba(255,215,91,.14);border-radius:12px;background:rgba(255,215,91,.05);color:#d8c99a;font-size:8px;line-height:1.5}
.faq-item{padding:13px;border:1px solid rgba(48,255,145,.14);border-radius:13px;background:#021910}
.faq-item+.faq-item{margin-top:7px}
.faq-item b{display:block;margin-bottom:3px;font-size:10px}
.faq-item p{margin:0!important;font-size:8.5px!important;line-height:1.5!important}
.legal-copy h3{margin:14px 0 5px;font-size:13px}
.legal-copy p{color:#94aa9d;font-size:9px;line-height:1.62}
.empty{padding:24px;color:var(--muted);text-align:center;font-size:10px}
.empty b{display:block;margin-bottom:4px;color:white;font-size:13px}
.drawer{position:fixed;z-index:100;left:0;top:0;bottom:0;width:min(78vw,318px);overflow:auto;overscroll-behavior:contain;padding:14px 12px 24px;border-right:1px solid rgba(48,255,145,.16);background:linear-gradient(180deg,#07140f 0%,#03170f 35%,#01110b 100%);transform:translateX(-102%);transition:transform .2s ease;box-shadow:18px 0 36px rgba(0,0,0,.25)}
.drawer-backdrop{position:fixed;z-index:90;inset:0;background:rgba(0,0,0,.66);opacity:0;pointer-events:none;transition:opacity .2s ease}
#drawer-toggle:checked ~ .app .drawer{transform:none}
#drawer-toggle:checked ~ .app .drawer-backdrop{opacity:1;pointer-events:auto}
.drawer-head{display:flex;align-items:center;gap:9px;padding:3px 1px 12px;border-bottom:1px solid rgba(255,255,255,.055)}




.drawer-close{width:36px;height:36px;display:grid;place-items:center;flex:0 0 36px;border:1px solid rgba(61,255,158,.13);border-radius:12px;background:#00170f;color:#f1fff6;font-size:19px}
.drawer-guide{display:flex;align-items:center;gap:9px;margin-top:12px;padding:11px 12px;border:1px solid rgba(61,255,158,.11);border-radius:14px;background:linear-gradient(145deg,rgba(255,214,94,.075),rgba(35,255,143,.035));color:#effff4}
.drawer-guide-ico{width:31px;height:31px;display:grid;place-items:center;flex:0 0 31px;border:1px solid rgba(255,217,105,.18);border-radius:10px;background:rgba(255,214,94,.065);font-size:14px}
.drawer-guide-copy{min-width:0}
.drawer-guide-copy b{display:block;font-size:9.5px}
.drawer-guide-copy small{display:block;margin-top:2px;color:#9ab2a5;font-size:6.5px;line-height:1.35}
.drawer-grid{display:grid;grid-template-columns:1fr 1fr;gap:8px;margin-top:12px}
.drawer-card{min-height:88px;display:flex;flex-direction:column;justify-content:space-between;padding:10px;border:1px solid rgba(61,255,158,.09);border-radius:14px;background:linear-gradient(145deg,#0a1612,#0d171e);color:#effff4;box-shadow:0 4px 12px rgba(0,0,0,.09);touch-action:manipulation}
.drawer-card:active{transform:scale(.985)}
.drawer-card.primary{background:linear-gradient(145deg,#0f2419,#072216)}
.drawer-card-icon{width:34px;height:34px;display:grid;place-items:center;border:1px solid rgba(61,255,158,.14);border-radius:11px;background:rgba(35,255,143,.05);color:#59ffac}
.drawer-card-icon svg{width:18px;height:18px;fill:none;stroke:currentColor;stroke-width:1.8;stroke-linecap:round;stroke-linejoin:round}
.drawer-card-copy b{display:block;margin-top:8px;font-size:9px;line-height:1.2}
.drawer-card-copy small{display:block;margin-top:2px;color:#8ba597;font-size:6.4px;line-height:1.3}
.drawer-card-foot{display:flex;align-items:center;justify-content:space-between;gap:6px;margin-top:8px}
.drawer-chip{padding:3px 6px;border:1px solid rgba(61,255,158,.10);border-radius:999px;color:#95b0a1;font-size:5.5px;font-weight:900;letter-spacing:.3px;text-transform:uppercase}
.drawer-card-arrow{color:#86a091;font-size:14px}
.drawer-section-title{margin:15px 3px 7px;color:#6f877a;font-size:6.5px;font-weight:1000;letter-spacing:1.1px;text-transform:uppercase}
.drawer-account-grid{display:grid;grid-template-columns:1fr 1fr;gap:8px}
.drawer-account-card{min-height:80px;display:flex;flex-direction:column;justify-content:space-between;padding:10px;border:1px solid rgba(61,255,158,.09);border-radius:14px;background:#07150f;color:#effff4;box-shadow:0 4px 12px rgba(0,0,0,.08);touch-action:manipulation}
.drawer-account-card.full{grid-column:1/-1;min-height:68px;flex-direction:row;align-items:center;gap:10px}
.drawer-account-icon{width:33px;height:33px;display:grid;place-items:center;flex:0 0 33px;border:1px solid rgba(61,255,158,.12);border-radius:10px;background:rgba(35,255,143,.045);color:#59ffac}
.drawer-account-icon svg{width:17px;height:17px;fill:none;stroke:currentColor;stroke-width:1.8;stroke-linecap:round;stroke-linejoin:round}
.drawer-account-copy{min-width:0;flex:1}
.drawer-account-copy b{display:block;font-size:8.5px}
.drawer-account-copy small{display:block;margin-top:2px;color:#819c8d;font-size:6.2px;line-height:1.3}
.drawer-account-arrow{color:#6f8a7b;font-size:15px}
.drawer-logout{width:100%;min-height:43px;display:flex;align-items:center;justify-content:center;gap:8px;margin-top:10px;border:1px solid rgba(255,101,111,.16);border-radius:13px;background:rgba(255,72,87,.035);color:#ff8b94;font-size:8px;font-weight:950;touch-action:manipulation}
.drawer-logout svg{width:16px;height:16px;fill:none;stroke:currentColor;stroke-width:1.8;stroke-linecap:round;stroke-linejoin:round}
.wallet-pro-shell-clean{padding-top:2px}
@media(max-width:380px){.drawer{width:min(80vw,300px)}.drawer-grid,.drawer-account-grid{gap:7px}.drawer-card{min-height:84px;padding:9px}.drawer-account-card{min-height:76px;padding:9px}}
.modal{position:fixed;z-index:120;inset:0;display:none;align-items:flex-end;background:rgba(0,0,0,.68)}
#game-info-toggle:checked ~ .app .modal{display:flex}
#game-info-toggle:checked ~ .app #gameLaunchModal{display:flex}
.modal-card{width:min(520px,100%);margin:auto 0 0;padding:16px 15px calc(18px + env(safe-area-inset-bottom));border:1px solid var(--line);border-bottom:0;border-radius:20px 20px 0 0;background:#041b12}
.modal-card h3{margin:0 0 7px}
.modal-close{float:right;width:35px;height:35px;display:grid;place-items:center;border:1px solid var(--line);border-radius:10px;background:#032017}
.bottom{position:fixed;z-index:70;left:50%;bottom:0;width:min(520px,100%);height:calc(76px + env(safe-area-inset-bottom));display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:3px;padding:7px 8px calc(7px + env(safe-area-inset-bottom));border-top:1px solid rgba(51,255,145,.20);background:linear-gradient(180deg,rgba(0,20,12,.985),rgba(0,11,7,.995));box-shadow:0 -10px 30px rgba(0,0,0,.36);transform:translateX(-50%)}
.nav{min-width:0;display:grid;place-items:center;align-content:center;gap:3px;padding:3px 2px;border-radius:14px;color:#81988b;font-size:8.6px;line-height:1;font-weight:900;transition:color .16s ease,background .16s ease}
.nav-icon{width:35px;height:31px;display:grid;place-items:center;border:1px solid rgba(91,125,105,.16);border-radius:11px;background:rgba(4,37,24,.42);box-shadow:inset 0 1px rgba(255,255,255,.025);transition:all .16s ease}
.nav-icon svg{width:20px;height:20px;overflow:visible}
