/* ===== V36 GAME DISCOVERY — scoped only to Lihat Semua Game ===== */
.view[data-view='games']{padding-bottom:calc(104px + env(safe-area-inset-bottom))}
.game-page-head{margin-bottom:8px}
.game-page-title{min-width:0;display:flex;flex-direction:column;gap:2px}
.game-page-title small{color:#6f8d7d;font-size:7.5px;line-height:1;font-weight:950;letter-spacing:1.15px}
.game-page-title h1{margin:0!important;font-size:19px!important;line-height:1.05}
.game-discovery-hero{position:relative;overflow:hidden;margin-bottom:10px;padding:14px;border:1px solid rgba(62,255,151,.19);border-radius:18px;background:radial-gradient(circle at 92% -8%,rgba(255,211,81,.12),transparent 30%),radial-gradient(circle at 0 100%,rgba(40,242,139,.10),transparent 34%),linear-gradient(145deg,#06261a,#02150e 72%);box-shadow:0 12px 28px rgba(0,0,0,.20),inset 0 1px rgba(255,255,255,.035)}
.game-hero-copy{position:relative;z-index:1;margin-bottom:11px}
.game-kicker{display:inline-flex;align-items:center;min-height:19px;padding:4px 7px;border:1px solid rgba(255,215,102,.22);border-radius:7px;background:rgba(65,48,7,.28);color:#ffd86c;font-size:6.8px;font-weight:1000;letter-spacing:.9px}
.game-hero-copy h2{margin:7px 0 3px;color:#f7fff9;font-size:18px;line-height:1.08;letter-spacing:-.35px;font-weight:1000}
.game-hero-copy p{margin:0;max-width:310px;color:#7f958a;font-size:8.5px;line-height:1.45;font-weight:650}
.game-provider-block{margin:2px 0 12px;padding:10px 0 0;border-top:1px solid rgba(255,255,255,.045)}
.game-provider-heading{display:flex;align-items:end;justify-content:space-between;gap:10px;margin-bottom:7px;padding:0 1px}
.game-provider-heading b{display:block;color:#effff5;font-size:11.5px;font-weight:950}
.game-provider-heading small{display:block;margin-top:1px;color:#657d71;font-size:7.4px;font-weight:700}
.game-provider-heading>span{max-width:48%;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;color:#58ffa8;font-size:7.8px;font-weight:900}
.game-provider-native{position:absolute!important;width:1px!important;height:1px!important;opacity:0!important;pointer-events:none!important}
.game-provider-strip{display:flex;gap:7px;min-height:39px;overflow-x:auto;overflow-y:hidden;padding:1px 10px 4px 1px;scrollbar-width:none;-webkit-overflow-scrolling:touch;scroll-snap-type:x proximity}
.game-provider-strip::-webkit-scrollbar{display:none}
.game-provider-chip{flex:0 0 auto;min-height:35px;padding:0 11px;border:1px solid rgba(61,255,153,.16);border-radius:11px;background:linear-gradient(180deg,#062218,#03170f);color:#83988d;font-size:8.2px;font-weight:900;white-space:nowrap;scroll-snap-align:start;cursor:pointer}
.game-provider-chip.active{border-color:rgba(82,255,166,.48);background:linear-gradient(180deg,#0a3826,#052219);color:#dcffec;box-shadow:0 0 0 1px rgba(70,244,153,.04),0 6px 16px rgba(7,190,94,.08)}
.game-catalog-heading{display:flex;align-items:flex-end;justify-content:space-between;gap:10px;margin:1px 1px 9px}
.game-catalog-heading span{display:block;color:#667f72;font-size:6.7px;font-weight:1000;letter-spacing:1px}
.game-catalog-heading h2{margin:2px 0 0;color:#f6fff9;font-size:15.5px;line-height:1.05;font-weight:1000;letter-spacing:-.2px}
.game-count{flex:0 0 auto;padding:5px 8px;border:1px solid rgba(62,255,151,.16);border-radius:8px;background:#031c13;color:#8da298;font-size:7.5px;font-weight:900}
.view[data-view='games'] .slot-grid{gap:8px}
.view[data-view='games'] .slot-card{border-radius:14px;background:linear-gradient(180deg,#06261b,#02140d);box-shadow:0 8px 20px rgba(0,0,0,.20),inset 0 1px rgba(255,255,255,.025)}
.view[data-view='games'] .slot-art{aspect-ratio:4/5}
.view[data-view='games'] .slot-body{padding:7px 6px 6px}
.view[data-view='games'] .slot-body b{font-size:9.3px}
.view[data-view='games'] .slot-body small{font-size:7px;margin-top:2px}
.view[data-view='games'] .play-btn{min-height:29px;margin-top:6px;border-radius:8px;font-size:8.4px}
.view[data-view='games'] .rtp-badge{left:5px;bottom:5px;padding:3px 5px;font-size:5.9px}
.view[data-view='games']
.game-filter-empty{grid-column:1/-1;margin-top:9px;padding:24px 15px;border:1px dashed rgba(70,255,160,.18);border-radius:14px;background:rgba(3,25,17,.58);text-align:center}
.game-filter-empty span{display:grid;place-items:center;width:34px;height:34px;margin:0 auto 8px;border:1px solid rgba(75,255,164,.18);border-radius:10px;background:#05261a;color:#63ffad;font-size:18px}
.game-filter-empty b{display:block;color:#eafff2;font-size:11px}
.game-filter-empty small{display:block;margin-top:3px;color:#71877b;font-size:8px}
@media(max-width:350px){
  .game-discovery-hero{padding:11px;border-radius:15px}
  .game-hero-copy h2{font-size:16.5px}
  .game-provider-chip{min-height:33px;padding:0 9px;font-size:7.7px}
  .view[data-view='games'] .slot-grid{gap:5px}
  .view[data-view='games'] .slot-body{padding:6px 5px 5px}
  .view[data-view='games'] .slot-body b{font-size:8.5px}
  .view[data-view='games'] .play-btn{font-size:8px}
}
@media(min-width:700px){
  .view[data-view='games'] .slot-grid{grid-template-columns:repeat(5,minmax(0,1fr));gap:10px}
  .game-discovery-hero{padding:18px}
  .game-hero-copy h2{font-size:22px}
}

