#registerNextBankBtn,#registerStepAccountBtn,#registerStepBankBtn,#registerBackAccountBtn{pointer-events:auto!important;position:relative;z-index:5}

/* ===== V35 BLOGGER AUTH INTERACTION HARD LOCK ===== */
.auth-password-control{position:relative!important}
.auth-password-control input{padding-right:54px!important}
.password-eye{position:absolute!important;right:6px!important;top:50%!important;transform:translateY(-50%)!important;z-index:120!important;pointer-events:auto!important}
.password-eye,.password-eye *{touch-action:manipulation!important;-webkit-tap-highlight-color:transparent!important}
#registerNextBankBtn,#registerStepBankBtn,#registerStepAccountBtn,#registerBackAccountBtn{z-index:80!important;pointer-events:auto!important}
.auth-panel-register[data-register-step='1'] .register-page[data-register-page='1']{display:block!important}
.auth-panel-register[data-register-step='1'] .register-page[data-register-page='2']{display:none!important}
.auth-panel-register[data-register-step='2'] .register-page[data-register-page='1']{display:none!important}.auth-panel-register[data-register-step='2'] .register-page[data-register-page='2']{display:block!important}

/* V50 — PREMIUM LIGHTWEIGHT DESIGN SYSTEM */
:root{
  --premium-surface:#031b12;
  --premium-surface-2:#061f16;
  --premium-border:rgba(72,255,161,.14);
  --premium-border-strong:rgba(72,255,161,.28);
  --premium-soft:#8ea79a;
  --premium-accent:#36ef91;
}
body{
  background:
    radial-gradient(circle at 50% -10%,rgba(46,239,145,.075),transparent 27%),
    linear-gradient(180deg,#00130c 0%,#000d08 48%,#000b07 100%);
}
.content{padding:10px 10px 14px}
.topbar{
  background:#00120b;
  border-bottom-color:rgba(67,255,157,.12);
  box-shadow:0 5px 16px rgba(0,0,0,.15);
}
.page-head,.account-subhead{
  min-height:44px;
  margin:1px 0 10px;
}
.page-head h1,.account-subhead h1{
  font-size:18px;
  letter-spacing:-.35px;
  font-weight:950;
}
.page-head .back,.account-subhead .back{
  border-color:rgba(66,255,159,.14);
  background:#031b12;
  box-shadow:none;
}
.screen-shell,.article-shell,.account-subpage,.profile-pro-shell,.wallet-flow-shell,.wallet-pro-shell{gap:10px}
.screen-hero,.page-hero,.article-cover,.account-intro,.wallet-flow-hero,.profile-pro-hero{
  border-color:rgba(66,255,159,.16);
  background:
    radial-gradient(circle at 94% 5%,rgba(49,239,143,.105),transparent 26%),
    linear-gradient(145deg,#062a1c,#00150e 74%);
  box-shadow:0 8px 20px rgba(0,0,0,.13);
}
.screen-hero h2,.page-hero h2{font-size:19px}
.screen-hero p,.page-hero p,.account-intro-copy span{color:#8fa79a}
.section-card,.article-body,.account-card,.profile-pro-section,.wallet-pro-panel,.wallet-flow-card{
  border-color:rgba(66,255,159,.12);
  background:linear-gradient(145deg,#031c13,#00140d);
  box-shadow:0 6px 16px rgba(0,0,0,.10);
}
.metric-box,.status-line,.menu-line,.row,.wallet-bank-summary,.wallet-recent-row,
.transaction-modern-row,.security-item,.saved-account-card,.settings-premium-row{
  border-color:rgba(66,255,159,.09);
  background:#00170f;
  box-shadow:none;
}
.btn,.account-primary-btn,.account-secondary-btn,.top-pill,.more,.play-btn{
  min-height:42px;
  touch-action:manipulation;
}
.btn.primary,.account-primary-btn{
  background:linear-gradient(145deg,#31ef91,#0fc974);
  box-shadow:0 7px 17px rgba(27,226,128,.12);
}
.btn.secondary,.account-secondary-btn{
  background:#021a11;
  border-color:rgba(66,255,159,.14);
}
input,select,textarea{font-size:16px}
.field input,.field select,.account-field input,.account-field select,.settings-premium-control{
  border-color:rgba(66,255,159,.13);
  background:#00170f;
}
.slot-card{
  border-color:rgba(70,255,160,.14);
  background:linear-gradient(180deg,#052218,#02140e);
  box-shadow:0 6px 15px rgba(0,0,0,.16);
}
.slot-card:active{box-shadow:0 3px 9px rgba(0,0,0,.13)}
.slot-art{background:#071b14}
.rtp-badge{
  border-color:rgba(65,255,157,.20);
  background:#062318;
  box-shadow:none;
}
.fallback-game-wait{
  opacity:.55;
  pointer-events:none;
  cursor:default;
}
.provider-card,.promo-card,.drawer-card,.drawer-mini-item{
  box-shadow:0 5px 14px rgba(0,0,0,.10);
}
.bottom{
  background:#00110b;
  border-top-color:rgba(65,255,157,.13);
  box-shadow:0 -5px 18px rgba(0,0,0,.24);
}
.bottom .nav{touch-action:manipulation}
.drawer{
  background:linear-gradient(180deg,#07140f 0%,#03170f 35%,#01110b 100%);
  box-shadow:18px 0 36px rgba(0,0,0,.25);
}
.drawer-card,.drawer-mini-item{touch-action:manipulation}
.drawer-card:active,.drawer-mini-item:active,.profile-menu-card:active,.profile-list-row:active{
  transform:scale(.985);
}
.catalog-empty{
  grid-column:1/-1;
  min-height:92px;
  display:grid;
  place-items:center;
  padding:16px;
  border:1px dashed rgba(67,255,159,.13);
  border-radius:15px;
  background:#00150e;
  color:#789386;
  text-align:center;
  font-size:8px;
}
.backend-state-note{
  margin-top:9px;
  padding:9px 10px;
  border:1px solid rgba(255,211,91,.14);
  border-radius:12px;
  background:rgba(255,211,91,.035);
  color:#b8ab82;
  font-size:7.5px;
  line-height:1.5;
}

/* paint containment for long mobile pages */
.slot-card,.promo-card,.provider-card,.section-card,.account-card,.profile-pro-section,
.wallet-pro-panel,.wallet-flow-card,.metric-box,.drawer-card,.drawer-mini-item{
  contain:layout paint style;
}
.section,.account-card,.profile-pro-section,.article-body,.promo-card{
  content-visibility:auto;
  contain-intrinsic-size:auto 140px;
}

/* low-GPU mobile path */
@media(max-width:420px){
  .hero,.screen-hero,.page-hero,.article-cover,.profile-pro-hero,.wallet-pro-balance,.wallet-flow-hero{
    box-shadow:0 6px 15px rgba(0,0,0,.12);
  }
  .slot-card,.section-card,.account-card,.profile-pro-section,.wallet-flow-card,.wallet-pro-panel{
    box-shadow:0 4px 12px rgba(0,0,0,.09);
  }
}
@media(prefers-reduced-motion:reduce){
  *,*:before,*:after{
    animation:none!important;
    transition:none!important;
    scroll-behavior:auto!important;
  }
}


/* V52 FINAL/FROZEN CLEANUP */
label[for^='route-'],label[for^='auth-'],button{touch-action:manipulation}
.catalog-empty{min-height:86px}
