#brandBoot{position:fixed;z-index:100000;inset:0;display:grid;place-items:center;background:radial-gradient(circle at 50% 42%,rgba(24,210,119,.12),transparent 30%),#000d08;opacity:0;visibility:hidden;pointer-events:none;transition:opacity .18s ease,visibility .18s ease}
