.brand-boot-inner{display:grid;justify-items:center;gap:12px}
.brand-boot-mark{width:88px;height:88px;background-image:var(--brandalbet-icon-round);background-repeat:no-repeat;background-position:center;background-size:contain;filter:drop-shadow(0 12px 30px rgba(0,0,0,.38));animation:brandBootPulse 1.35s ease-in-out infinite}
.brand-boot-line{width:74px;height:3px;overflow:hidden;border-radius:999px;background:rgba(255,255,255,.08)}
.brand-boot-line:after{content:"";display:block;width:42%;height:100%;border-radius:inherit;background:linear-gradient(90deg,#b88a37,#f2d28a,#2bea8b);animation:brandBootBar 1.15s ease-in-out infinite}
@keyframes brandBootPulse{0%,100%{transform:scale(.97);opacity:.82}50%{transform:scale(1.035);opacity:1}}
