/* ===== V71 FAST GAME NAV + PROVIDER-FIRST UX ===== */
button,label[for],a,[role='button'],.nav,.drawer-card{touch-action:manipulation;-webkit-tap-highlight-color:transparent}
.view[data-view='home'] .more{position:relative;min-height:26px!important;height:26px!important;padding:0 8px!important;border-radius:999px!important;border-color:rgba(72,255,162,.22)!important;background:linear-gradient(180deg,rgba(8,43,29,.96),rgba(3,24,16,.98))!important;color:#d9ffea!important;font-size:9px!important;font-weight:950!important;box-shadow:inset 0 1px rgba(255,255,255,.04),0 4px 12px rgba(0,0,0,.12)!important;transition:transform .12s ease,border-color .12s ease,background .12s ease!important}
.view[data-view='home'] .more:active{transform:scale(.96);border-color:rgba(80,255,169,.48)!important;background:linear-gradient(180deg,#0b3b28,#052419)!important}
.view[data-view='games']{contain:layout style;padding-top:0!important}
.view[data-view='games'] .game-page-head{margin-bottom:4px!important}
.view[data-view='games'] .game-provider-block.provider-first{margin:0 0 10px!important;padding:10px 0 8px!important;border-top:0!important;border-bottom:1px solid rgba(255,255,255,.045)}
.view[data-view='games'] .game-provider-strip{gap:7px;min-height:37px;padding:1px 8px 4px 1px;scroll-snap-type:x proximity;overscroll-behavior-x:contain}
.view[data-view='games'] .game-provider-chip{min-height:34px;padding:0 11px;border-radius:999px;border:1px solid rgba(61,255,153,.16);background:#061b12;color:#81968a;box-shadow:none;transition:background .10s ease,border-color .10s ease,color .10s ease,box-shadow .10s ease,transform .10s ease;touch-action:manipulation;-webkit-tap-highlight-color:transparent}
.view[data-view='games'] .game-provider-chip:active{transform:scale(.96)}
.view[data-view='games'] .game-provider-chip.active{border-color:#35f693!important;background:linear-gradient(180deg,#18dc7d,#0bae62)!important;color:#001b0e!important;box-shadow:0 0 0 1px rgba(72,255,160,.16),0 7px 18px rgba(16,211,111,.20)!important}
.view[data-view='games'] .game-provider-heading>span{color:#58ffa8!important}
.view[data-view='games'] .compact-game-heading{margin-top:4px!important;margin-bottom:8px!important}
.view[data-view='games'] #allSlotGrid{contain:layout style}
.view[data-view='games'] #allSlotGrid>.slot-card{contain:layout paint style;content-visibility:auto;contain-intrinsic-size:140px 230px}
.view[data-view='games'] .game-load-sentinel{display:block;min-height:44px;margin:12px auto 0;padding:8px 16px;border:1px solid #215539;border-radius:999px;background:#062218;color:#aaffcd;font-size:11px;cursor:pointer}
.view[data-view='games'] .game-load-sentinel[hidden]{display:none}
@media(max-width:380px){.view[data-view='home'] .more{height:25px!important;min-height:25px!important;padding:0 8px!important;font-size:8.5px!important}.view[data-view='games'] .game-provider-chip{min-height:32px;padding:0 10px;font-size:7.6px}}
.view[data-view='home'] .more::after{content:'';position:absolute;inset:-9px 0}
.view[data-view='games'] .game-provider-chip[aria-pressed='true']{background:#20e88b!important;border-color:#54ffac!important;color:#002411!important;box-shadow:0 0 10px rgba(32,232,139,.22)!important}
.view[data-view='games'] .game-provider-chip{transition:none;min-height:44px;font-size:10px}
.view[data-view='games'] .game-provider-chip:focus-visible,.view[data-view='home'] .more:focus-visible{outline:2px solid #54ffac;outline-offset:3px}
/* ===== /V71 ===== */

/* ===== V68 GAME CATALOG — FULL CARD ART + FAKE RTP + CENTER MODAL ===== */
.slot-grid{gap:8px!important;align-items:stretch!important}
.slot-card{cursor:pointer;border-radius:16px!important;background:linear-gradient(180deg,#101613 0%,#090d0b 100%)!important;border:1px solid rgba(70,255,159,.20)!important;box-shadow:0 12px 30px rgba(0,0,0,.24)!important;overflow:hidden!important;display:flex;flex-direction:column;min-height:100%}
.slot-card:focus-visible{outline:2px solid #49ffa4;outline-offset:2px}
.slot-card .slot-art{position:relative;aspect-ratio:3/4!important;display:flex;align-items:stretch;justify-content:stretch;background:radial-gradient(circle at 50% 0,rgba(61,255,166,.06),transparent 35%),linear-gradient(180deg,#111815 0%,#070b09 100%)!important;overflow:hidden;padding:0}
.slot-card .slot-art:after{content:"";position:absolute;left:0;right:0;bottom:0;height:18%;pointer-events:none;background:linear-gradient(180deg,transparent,rgba(0,0,0,.22))}
.slot-card .slot-art img{width:100%;height:100%;display:block;object-fit:cover!important;object-position:center top!important;background:#0a0f0c;transition:transform .2s ease}
.slot-card:active .slot-art img{transform:scale(.99)!important}
.slot-card .catalog-corner-play{display:none!important}
.slot-card .catalog-tag{position:absolute;z-index:5;left:50%;top:6px;transform:translateX(-50%);min-width:68px;max-width:82%;padding:5px 10px;border-radius:999px;background:#20eaa0;color:#00170d;font-size:6.5px;line-height:1;font-weight:1000;letter-spacing:.35px;text-transform:uppercase;text-align:center;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;box-shadow:0 4px 12px rgba(0,0,0,.24)}
.slot-card .catalog-tag.promo{background:#ff6670;color:#fff}
.slot-card .card-rtp{display:grid;grid-template-columns:auto 1fr auto;align-items:center;gap:6px;padding:8px 9px 6px;background:rgba(15,19,17,.98);border-top:1px solid rgba(255,255,255,.04)}
.slot-card .card-rtp-label{color:#d8e0db;font-size:6.8px;font-weight:900;letter-spacing:.18px}
.slot-card .card-rtp-track{height:9px;overflow:hidden;border-radius:999px;background:#2b332f;box-shadow:inset 0 1px 2px rgba(0,0,0,.32)}
.slot-card .card-rtp-fill{height:100%;width:0;border-radius:inherit;background:linear-gradient(90deg,#17dc79,#53f7a2);transition:width .25s ease}
.slot-card .card-rtp-fill.medium{background:linear-gradient(90deg,#e3b631,#ffd45c)}
.slot-card .card-rtp-fill.low{background:linear-gradient(90deg,#ef6572,#ff8a70)}
.slot-card .card-rtp-value{min-width:40px;text-align:right;color:#dce5df;font-size:6.6px;font-weight:850}
.slot-card .slot-body{padding:1px 9px 10px;background:rgba(15,19,17,.98)}
.slot-card .card-title-row{display:flex;align-items:flex-start;gap:6px;min-width:0}
.slot-card .card-title-row b{flex:1;min-width:0;display:-webkit-box;overflow:hidden;-webkit-line-clamp:2;-webkit-box-orient:vertical;white-space:normal;color:#f2faf5;font-size:8.6px;line-height:1.24;font-weight:850;min-height:2.48em;word-break:break-word}
.slot-card .card-fav{width:20px;height:20px;flex:0 0 20px;display:grid;place-items:center;border:0;background:transparent;color:#89968e;font-size:15px;line-height:1;cursor:pointer;margin-top:1px}
.slot-card .card-fav.is-fav{color:#ffd45c}
.slot-card .play-btn,.slot-card .rtp-badge{display:none!important}

#gameLaunchModal{align-items:center!important;justify-content:center!important;padding:12px!important;background:rgba(0,6,4,.82)!important;backdrop-filter:blur(10px);-webkit-backdrop-filter:blur(10px)}
#gameLaunchModal .modal-card{position:relative;width:min(454px,calc(100vw - 20px))!important;max-height:calc(100dvh - 24px);overflow:auto;padding:0!important;border-radius:26px!important;border:1px solid rgba(72,255,165,.20)!important;background:radial-gradient(circle at 50% -12%,rgba(42,255,151,.11),transparent 28%),linear-gradient(180deg,#111815 0%,#070d0a 100%)!important;box-shadow:0 34px 100px rgba(0,0,0,.68),inset 0 1px rgba(255,255,255,.03)!important;overscroll-behavior:contain;scrollbar-width:none}
#gameLaunchModal .modal-card::-webkit-scrollbar{display:none}
#gameLaunchModal .game-modal-top{position:sticky;top:0;z-index:12;display:flex;align-items:center;gap:10px;padding:15px 16px 13px;border-bottom:1px solid rgba(255,255,255,.06);background:rgba(13,20,16,.94);backdrop-filter:blur(12px)}
#gameLaunchModal .game-modal-title{flex:1;min-width:0;margin:0!important;color:#f7fff9;font-size:17px;line-height:1.2;font-weight:1000;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
#gameLaunchModal .modal-close{position:static!important;float:none!important;width:36px;height:36px;flex:0 0 36px;display:grid;place-items:center;border:1px solid rgba(255,255,255,.12);border-radius:12px;background:#17201c;color:#fff;font-size:21px;line-height:1}
#gameLaunchModal .game-preview-main{display:grid;grid-template-columns:minmax(0,1.04fr) minmax(0,.96fr);gap:12px;padding:14px 14px 0}
#gameLaunchModal .game-preview-art{position:relative;width:100%;aspect-ratio:3/4;overflow:hidden;border:1px solid rgba(255,255,255,.08);border-radius:18px;background:radial-gradient(circle at 50% 0,rgba(61,255,166,.07),transparent 33%),#0b100d;padding:0;box-shadow:inset 0 1px rgba(255,255,255,.025)}
#gameLaunchModal .game-preview-art:after{display:none!important}
#gameLaunchModal .game-preview-art img{width:100%;height:100%;display:block;object-fit:cover!important;object-position:center top!important;background:#080c0a}
#gameLaunchModal .game-preview-empty{width:100%;height:100%;display:grid;place-items:center;padding:12px;color:#6f887a;font-size:9px;text-align:center}
#gameLaunchModal .game-preview-info{display:flex;flex-direction:column;min-width:0;border:1px solid rgba(255,255,255,.055);border-radius:18px;background:linear-gradient(180deg,#121916,#0c120f);padding:12px}
#gameLaunchModal .game-preview-provider-label{display:block;margin-bottom:3px;color:#62786d;font-size:7px;font-weight:900;letter-spacing:.8px;text-transform:uppercase}
#gameLaunchModal .game-preview-provider{display:block;color:#e5f0e9;font-size:11px;font-weight:950;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
#gameLaunchModal .game-preview-meta-row{margin-top:10px;padding-top:9px;border-top:1px solid rgba(255,255,255,.055)}
#gameLaunchModal .game-preview-meta-value{display:block;margin-top:3px;color:#c7d5cd;font-size:8.4px;font-weight:800;line-height:1.35;word-break:break-word}
#gameLaunchModal .game-preview-fav{margin-top:auto;min-height:34px;display:flex;align-items:center;justify-content:center;gap:6px;border:1px solid rgba(255,255,255,.07);border-radius:10px;background:#171d1a;color:#cbd7cf;font-size:8px;font-weight:900}
#gameLaunchModal .game-preview-fav.is-fav{color:#ffe37b;border-color:rgba(255,222,105,.20)}
#gameLaunchModal .game-preview-content{padding:0 14px 16px!important;margin:0!important}
#gameLaunchModal .game-preview-status{display:grid;grid-template-columns:auto 1fr auto;align-items:center;gap:8px;margin:12px 0 0!important;padding:11px 12px;border:1px solid rgba(255,255,255,.055);border-radius:14px;background:#0d1410}
#gameLaunchModal .game-preview-rtp-label{color:#7f9589;font-size:7px;font-weight:900;letter-spacing:.2px}
#gameLaunchModal .game-preview-rtp-track{height:11px;overflow:hidden;border-radius:999px;background:#27302b}
#gameLaunchModal .game-preview-rtp-fill{height:100%;width:0;border-radius:inherit;background:linear-gradient(90deg,#15d975,#55f4a2);transition:width .2s ease}
#gameLaunchModal .game-preview-rtp-value{min-width:43px;color:#e7f3eb;font-size:7.3px;font-weight:950;text-align:right}
#gameLaunchModal .game-preview-desc{margin-top:12px;padding:12px 13px;border:1px solid rgba(255,255,255,.055);border-radius:14px;background:#0b100d}
#gameLaunchModal .game-preview-desc small{display:block;margin-bottom:5px;color:#687e72;font-size:7px;font-weight:900;letter-spacing:.8px;text-transform:uppercase}
#gameLaunchModal .game-preview-desc p{margin:0!important;color:#b8c9bf!important;font-size:8.7px!important;line-height:1.55!important}
#gameLaunchModal .game-preview-actions{display:grid;grid-template-columns:1fr;gap:8px;margin-top:13px!important}
#gameLaunchModal .game-preview-play,#gameLaunchModal .game-preview-login{min-height:47px;border:0;border-radius:13px;background:linear-gradient(180deg,#50ffa4,#16d978);color:#00170c;font-size:10.5px;font-weight:1000;box-shadow:0 9px 24px rgba(16,210,111,.14);display:flex;align-items:center;justify-content:center;text-align:center}
#gameLaunchModal .game-preview-play[disabled]{opacity:.58;cursor:not-allowed}
@media(max-width:380px){.slot-grid{gap:6px!important}.slot-card .card-rtp{gap:4px;padding:7px 7px 5px}.slot-card .card-title-row b{font-size:7.9px}.slot-card .slot-body{padding:1px 7px 9px}#gameLaunchModal{padding:8px!important}#gameLaunchModal .modal-card{width:calc(100vw - 12px)!important;border-radius:22px!important}#gameLaunchModal .game-preview-main{gap:9px;padding:11px 11px 0}#gameLaunchModal .game-preview-info{padding:9px}#gameLaunchModal .game-preview-content{padding:0 11px 13px!important}}
/* ===== /V68 ===== */


/* V73: wide RTP track with percentage on its own heading row. */
.slot-card .card-rtp{grid-template-columns:minmax(0,1fr) auto;gap:5px 4px}
.slot-card .card-rtp-label{grid-column:1;grid-row:1;font-size:6.5px;white-space:nowrap}
.slot-card .card-rtp-value{grid-column:2;grid-row:1;min-width:0;font-size:8px;color:#62ffad}
.slot-card .card-rtp-track{grid-column:1/-1;grid-row:2;width:100%;height:10px}

/* V74: indicators overlay the image, without a footer or extra height. */
.hero-pagination{position:absolute;z-index:3;bottom:4px;left:50%;transform:translateX(-50%);display:flex;gap:0;padding:0 5px;border-radius:999px;background:rgba(0,20,12,.38)}
.hero-dot{display:grid;place-items:center;width:24px;height:24px;padding:0;border:0;background:transparent;cursor:pointer;touch-action:manipulation}
.hero-dot::after{content:'';display:block;width:6px;height:6px;border-radius:50%;background:#297d53;box-shadow:0 0 0 1px rgba(255,255,255,.18)}
.hero-dot[aria-current='true']::after{background:#39ff98;box-shadow:0 0 7px rgba(57,255,152,.8)}
.hero-dot:focus-visible{outline:1px solid #39ff98;border-radius:50%}

body.script:
//
    window.BrandalbetConfig=Object.freeze({
      apiBase:'https://brandalbet-backend.rkmpbajangda.workers.dev',
      memberOrigin:'https://brandalbet.blogspot.com',
      version:'V76_GAME_CATALOG_RESTORE_FINAL',
      performance:Object.freeze({publicCacheTtlMs:120000,publicStaleTtlMs:604800000}),
      payment:Object.freeze({
        depositEndpoint:'/api/payment-deposit',
        withdrawEndpoint:'/api/payment-withdraw',
        depositChannel:'QRIS',
        discovery:'auto'
      })
    });
//

//
    (function(){
      const $=(q)=>document.querySelector(q);
      const $$=(q)=>Array.from(document.querySelectorAll(q));
      const provider=$('#slotProvider');
      const resultCount=$('#gameResultCount');
      const filterEmpty=$('#gameFilterEmpty');
      const catalogTitle=$('#gameCatalogTitle');
      const providerState=$('#gameProviderState');
      const providerChipHost=$('#gameProviderChips');
      const loadSentinel=$('#gameLoadSentinel');
      const CATALOG_BATCH_SIZE=18;
      let catalogGames=[];
      let gamesByProvider=new Map();
      let activeProviderValue='Semua Provider';
      let renderedProviderValue=null;
      let renderedCatalogCount=0;
      let renderFrame=0;
      let pendingReset=false;
      function syncProviderChipState(value){
        activeProviderValue=String(value||'Semua Provider');
        $$('#gameProviderChips .game-provider-chip').forEach(item=>{
          const selected=item.dataset.providerValue===activeProviderValue;
          item.classList.toggle('active',selected);
          item.setAttribute('aria-pressed',String(selected));
        });
        if(providerState)providerState.textContent=activeProviderValue;
        if(catalogTitle)catalogTitle.textContent=activeProviderValue==='Semua Provider'?'Semua Game':activeProviderValue;
      }
      function providerGames(value){
        return value==='Semua Provider'?catalogGames:(gamesByProvider.get(value)||[]);
      }
      function renderCatalogPage(value=activeProviderValue,reset=true){
        const grid=$('#allSlotGrid');
        if(!grid||!catalogGames.length)return;
        const selected=String(value||'Semua Provider');
        const games=providerGames(selected);
        // Keep existing cards when returning to the same provider.
        if(reset&&renderedProviderValue===selected&&renderedCatalogCount>0)return;
        const changed=renderedProviderValue!==selected;
        const count=changed?0:renderedCatalogCount;
        const target=Math.min(games.length,count+CATALOG_BATCH_SIZE);
        const fragment=document.createDocumentFragment();
        for(let i=count;i<target;i++)fragment.appendChild(createCatalogCard(games[i]));
        if(changed)grid.replaceChildren(fragment);
        else grid.appendChild(fragment);
        renderedProviderValue=selected;
        renderedCatalogCount=target;
        if(resultCount)resultCount.textContent=games.length+' game';
        if(filterEmpty)filterEmpty.hidden=games.length!==0;
        if(loadSentinel)loadSentinel.hidden=target>=games.length;
      }
      function scheduleProviderRender(value,reset=true){
        const selected=String(value||provider?.value||'Semua Provider');
        // A pending filter change takes priority over an observer append.
        pendingReset=pendingReset||reset;
        if(renderFrame)cancelAnimationFrame(renderFrame);
        renderFrame=requestAnimationFrame(()=>{
          renderFrame=0;
          const shouldReset=pendingReset;
          pendingReset=false;
          renderCatalogPage(selected,shouldReset);
        });
      }
      function selectProvider(value){
        if(!provider)return;
        provider.value=value;
        syncProviderChipState(provider.value);
        scheduleProviderRender(provider.value,true);
      }
      providerChipHost?.addEventListener('click',(event)=>{
        const chip=event.target.closest('.game-provider-chip');
        if(!chip||!providerChipHost.contains(chip))return;
        selectProvider(chip.dataset.providerValue||'Semua Provider');
      });
      function buildProviderChips(){
        if(!providerChipHost||!provider)return;
        const fragment=document.createDocumentFragment();
        Array.from(provider.options).forEach(option=>{
          const chip=document.createElement('button');
          chip.type='button';
          chip.className='game-provider-chip';
          chip.textContent=option.textContent;
          chip.dataset.providerValue=option.value;
          fragment.appendChild(chip);
        });
        providerChipHost.replaceChildren(fragment);
        syncProviderChipState(provider.value||'Semua Provider');
      }
      provider?.addEventListener('change',()=>selectProvider(provider.value));
      loadSentinel?.addEventListener('click',()=>scheduleProviderRender(activeProviderValue,false));
      if(loadSentinel&&'IntersectionObserver' in window){
        const observer=new IntersectionObserver(entries=>{
          if(!entries.some(entry=>entry.isIntersecting))return;
          if($('#route-games')?.checked&&!loadSentinel.hidden)scheduleProviderRender(activeProviderValue,false);
        },{rootMargin:'160px 0px'});
        observer.observe(loadSentinel);
      }
      buildProviderChips();
      // Keep every route opening from the top and close the drawer automatically.
      const drawerElement=document.querySelector('.drawer');
      drawerElement?.addEventListener('click',(event)=>{
        const target=event.target.closest?.('label[for]');
        if(!target||target.getAttribute('for')==='drawer-toggle')return;
        const drawer=$('#drawer-toggle');if(drawer)drawer.checked=false;
      });
      $$('.route-radio').forEach(route=>{
        route.addEventListener('change',()=>{
          if(route.checked){
            const drawer=$('#drawer-toggle'); if(drawer) drawer.checked=false;
            window.scrollTo({top:0,left:0,behavior:'auto'});
            if(route.id==='route-games')scheduleProviderRender(provider?.value||activeProviderValue,true);
          }
        });
      });
      const GAME_CATALOG_ENDPOINT=((window.BrandalbetConfig&&window.BrandalbetConfig.apiBase)||'https://brandalbet-backend.rkmpbajangda.workers.dev')+'/api/games';
      function decodeHtmlEntities(value){
        const t=document.createElement('textarea');
        t.innerHTML=String(value||'');
        return t.value;
      }
      function sanitizeGameText(value,fallback='Slot Game'){
        let s=decodeHtmlEntities(String(value||''));
        s=s.replace(/<[^>]*>/g,' ');
        s=s.replace(/\[(?:color|colour)(?:=[^\]]+)?\]/gi,' ').replace(/\[\/(?:color|colour)\]/gi,' ');
        s=s.replace(/\{(?:color|colour)[:=][^}]+\}/gi,' ');
        s=s.replace(/(?:^|\s)(?:#|0x)?[0-9a-f]{6,8}(?=\s|$)/gi,' ');
        s=s.replace(/\^[0-9a-f]/gi,' ').replace(/§[0-9a-fk-or]/gi,' ');
        s=s.replace(/\x1b\[[0-9;]*m/g,' ');
        s=s.replace(/(?:font-?color|text-?color)\s*[:=]\s*[^\s]+/gi,' ');
        s=s.replace(/[_|]{2,}/g,' ');
        s=s.replace(/\s+/g,' ').trim();
        return s||fallback;
      }
      function safeGameDescription(game){
        const name=sanitizeGameText(game&&game.name,'Game');
        const provider=sanitizeGameText(game&&game.providerName,'provider');
        return `${name} tersedia melalui ${provider}. Detail permainan ditampilkan dengan gambar penuh tanpa pemotongan. Tekan Main Sekarang untuk membuka game.`;
      }
      function normalizeCatalogGame(raw,index){
        if(!raw||typeof raw!=='object') return null;
        const providerId=Number(raw.providerId||raw.provider?.id||0);
        const providerName=sanitizeGameText(raw.providerName||raw.provider?.name||raw.provider||'Provider','Provider');
        const symbol=String(raw.gameSymbol||raw.gameCode||raw.id||'').trim();
        if(!Number.isSafeInteger(providerId)||providerId<=0||!symbol) return null;
        return {
          id:String(raw.id||raw.gameCode||symbol||`${providerId}-${index}`),
          gameSymbol:symbol,
          name:sanitizeGameText(raw.name||raw.gameName||raw.title||symbol||'Slot','Slot Game'),
          providerId,
          providerName,
          category:sanitizeGameText(raw.category||raw.gameType||raw.type||'Slot Online','Slot Online'),
          image:String(raw.imageUrl||raw.image||raw.thumbnail||raw.icon||''),
          popular:raw.popular===true||raw.isPopular===true,
          isNew:raw.isNew===true||raw.new===true,
          pinned:raw.pinned===true,
          displayOrder:(raw.displayOrder&&typeof raw.displayOrder==='object')?raw.displayOrder:{},
          rtp:(()=>{const n=Number(raw.rtp??raw.rtpPercent??raw.returnToPlayer??raw.rtpValue);return Number.isFinite(n)&&n>0&&n<=100?n:0;})(),
          active:raw.active!==false&&raw.launchEnabled!==false&&raw.status!=='disabled'
        };
      }
      function uniqueCatalogGames(list){
        const used=new Set();
        return list.filter(game=>{
          if(!game||!game.active) return false;
          const key=`${game.providerId}::${game.id}`;
          if(used.has(key)) return false;
          used.add(key);
          return true;
        });
      }
      const demoRtpByGame=new Map();
      function getDisplayRtp(game){
        const baseValue=Number(game&&game.rtp||0);
        if(Number.isFinite(baseValue)&&baseValue>0&&baseValue<=100)return Math.round(baseValue*100)/100;
        const key=String(game.providerId)+'::'+String(game.id);
        if(!demoRtpByGame.has(key))demoRtpByGame.set(key,Math.round((90+Math.random()*8.9)*100)/100);
        return demoRtpByGame.get(key);
      }
      function createCatalogCard(game){
        const article=document.createElement('article');
        article.className='slot-card game-preview-trigger';
        article.tabIndex=0;
        article.setAttribute('role','button');
        article.setAttribute('aria-label',`Lihat ${game.name}`);
        article.dataset.gameId=game.id;
        article.dataset.gameSymbol=game.gameSymbol;
        article.dataset.providerId=String(game.providerId);
        article.dataset.gameName=game.name;
        article.dataset.providerName=game.providerName;
        article.dataset.category=game.category||'Slot Online';
        article.dataset.image=game.image||'';
        const displayRtp=getDisplayRtp(game);
        article.dataset.rtp=String(displayRtp);
        article.dataset.rtpSimulated=String(!(Number(game.rtp)>0&&Number(game.rtp)<=100));
        article.dataset.name=game.name.toLowerCase();
        article.dataset.provider=game.providerName.toLowerCase();
        article.dataset.popular=game.popular?'1':'0';
        article.dataset.new=game.isNew?'1':'0';

        const art=document.createElement('div');
        art.className='slot-art';
        if(game.isNew||game.popular){
          const tag=document.createElement('span');
          tag.className='catalog-tag'+(game.popular&&!game.isNew?' promo':'');
          tag.textContent=game.isNew?'NEW':'POPULAR';
          art.appendChild(tag);
        }
        const img=document.createElement('img');
        img.alt=game.name;
        img.loading='lazy';
        img.decoding='async';
        if(game.image) img.src=game.image;
        img.addEventListener('error',()=>{img.removeAttribute('src');img.alt='Gambar game tidak tersedia';},{once:true});
        art.appendChild(img);

        const rtp=document.createElement('div');
        rtp.className='card-rtp';
        const label=document.createElement('span');label.className='card-rtp-label';label.textContent=article.dataset.rtpSimulated==='true'?'RTP · SIMULASI':'RTP';
        const track=document.createElement('div');track.className='card-rtp-track';
        const fill=document.createElement('div');fill.className='card-rtp-fill';
        const rtpValue=Number(displayRtp||0);
        if(rtpValue>0){
          fill.style.width=Math.max(0,Math.min(100,rtpValue))+'%';
          if(rtpValue<80)fill.classList.add('low'); else if(rtpValue<90)fill.classList.add('medium');
        }else{
          fill.style.width='0%';fill.style.opacity='.45';
        }
        track.appendChild(fill);
        const value=document.createElement('span');value.className='card-rtp-value';value.textContent=rtpValue>0?rtpValue.toFixed(2)+'%':'LIVE';
        rtp.append(label,track,value);

        const body=document.createElement('div');
        body.className='slot-body';
        const titleRow=document.createElement('div');titleRow.className='card-title-row';
        const title=document.createElement('b');title.textContent=game.name;
        const fav=document.createElement('button');fav.type='button';fav.className='card-fav';fav.setAttribute('aria-label','Favorit');fav.textContent='★';
        fav.addEventListener('click',ev=>{ev.preventDefault();ev.stopPropagation();fav.classList.toggle('is-fav');});
        titleRow.append(title,fav);
        body.appendChild(titleRow);
        article.append(art,rtp,body);
        return article;
      }
      function renderCatalogGrid(selector,games){
        const grid=document.querySelector(selector);
        if(!grid) return;
        grid.innerHTML='';
        if(!games.length){
          const empty=document.createElement('div');
          empty.className='catalog-empty';
          empty.textContent='Belum ada game aktif.';
          grid.appendChild(empty);
          return;
        }
        const fragment=document.createDocumentFragment();
        games.forEach(game=>fragment.appendChild(createCatalogCard(game)));
        grid.appendChild(fragment);
      }
      function orderCurated(list,field){
        return [...list].sort((a,b)=>{
          const av=Number(a.displayOrder&&a.displayOrder[field]);
          const bv=Number(b.displayOrder&&b.displayOrder[field]);
          const aa=Number.isFinite(av)?av:999999;
          const bb=Number.isFinite(bv)?bv:999999;
          return aa-bb;
        });
      }
      function splitCatalogForHome(games,displayMeta){
        const curated=Number(displayMeta&&displayMeta.revision||0)>0;
        const popular=orderCurated(games.filter(game=>game.popular),'popular').slice(0,6);
        const popularKeys=new Set(popular.map(game=>`${game.providerId}::${game.id}`));
        const latest=orderCurated(games.filter(game=>game.isNew&&!popularKeys.has(`${game.providerId}::${game.id}`)),'newest').slice(0,6);
        const used=new Set([...popular,...latest].map(game=>`${game.providerId}::${game.id}`));
        // Before an admin has saved curation, keep a useful fallback home.
        // After revision > 0, the backoffice selection is authoritative: no auto-filled games.
        if(!curated){
          for(const game of games){
            if(popular.length>=6)break;
            const key=`${game.providerId}::${game.id}`;
            if(!used.has(key)){popular.push(game);used.add(key)}
          }
          for(const game of games){
            if(latest.length>=6)break;
            const key=`${game.providerId}::${game.id}`;
            if(!used.has(key)){latest.push(game);used.add(key)}
          }
        }
        return {popular,latest,remaining:games.filter(game=>!used.has(`${game.providerId}::${game.id}`))};
      }
      const PUBLIC_CACHE_TTL=Number(window.BrandalbetConfig?.performance?.publicCacheTtlMs||300000);
      const PUBLIC_STALE_TTL=Number(window.BrandalbetConfig?.performance?.publicStaleTtlMs||604800000);
      const PUBLIC_GAME_CACHE_KEY='brandalbet.public.games.v6';
      const LEGACY_GAME_CACHE_KEYS=['brandalbet.public.games.v5','brandalbet.public.games.v4','brandalbet.public.games.v3'];
      let catalogLoadPromise=null;
      let catalogCheckedAt=0;
      let appliedCatalogSignature='';
      function readStorageValue(storage,key){
        try{return storage&&storage.getItem?storage.getItem(key):null;}catch(_e){return null;}
      }
      function writeStorageValue(storage,key,value){
        try{if(storage&&storage.setItem)storage.setItem(key,value);}catch(_e){}
      }
      function readPublicCache(key){
        try{
          const raw=readStorageValue(window.localStorage,key)||readStorageValue(window.sessionStorage,key);
          if(!raw)return null;
          const parsed=JSON.parse(raw);
          const savedAt=Number(parsed&&parsed.savedAt||0);
          const age=Math.max(0,Date.now()-savedAt);
          if(!parsed||!parsed.value||!savedAt||age>PUBLIC_STALE_TTL)return null;
          return {value:parsed.value,age,fresh:age<=PUBLIC_CACHE_TTL};
        }catch(_e){return null;}
      }
      function writePublicCache(key,value){
        const raw=JSON.stringify({savedAt:Date.now(),value});
        writeStorageValue(window.localStorage,key,raw);
        writeStorageValue(window.sessionStorage,key,raw);
      }
      function applyProviderCatalogPayload(payload){
        if(!payload||payload.ok!==true||!Array.isArray(payload.games))return false;
        const signature=JSON.stringify([payload.games,payload.providers,payload.display]);
        if(signature===appliedCatalogSignature)return true;
        const previousProvider=activeProviderValue;
        const games=uniqueCatalogGames(payload.games.map(normalizeCatalogGame).filter(Boolean));
        if(!games.length)return false;
        const home=splitCatalogForHome(games,payload.display);
        renderCatalogGrid('#homePopularGrid',home.popular);
        renderCatalogGrid('#homeLatestGrid',home.latest);
        const homeAllCount=games.length<3?games.length:Math.min(18,Math.max(3,Math.floor(games.length/3)*3));
        renderCatalogGrid('#homeAllGrid',games.slice(0,homeAllCount));
        catalogGames=games;
        gamesByProvider=new Map();
        games.forEach(game=>{
          if(!gamesByProvider.has(game.providerName))gamesByProvider.set(game.providerName,[]);
          gamesByProvider.get(game.providerName).push(game);
        });
        appliedCatalogSignature=signature;
        renderedProviderValue=null;
        renderedCatalogCount=0;
        const providerSelect=document.querySelector('#slotProvider');
        if(providerSelect){
          const availableNames=new Set(games.map(g=>g.providerName));
          const orderedFromBackend=Array.isArray(payload.providers)?payload.providers.map(p=>String(p&&p.providerName||'')).filter(name=>name&&availableNames.has(name)):[];
          const remainder=[...availableNames].filter(name=>!orderedFromBackend.includes(name)).sort();
          const providers=[...new Set([...orderedFromBackend,...remainder])];
          providerSelect.innerHTML='<option>Semua Provider</option>';
          providers.forEach(name=>{
            const option=document.createElement('option');
            option.value=name;option.textContent=name;providerSelect.appendChild(option);
          });
          providerSelect.value=availableNames.has(previousProvider)?previousProvider:'Semua Provider';
          buildProviderChips();
          // Prepare a small first page, so opening the catalog can reuse its DOM.
          scheduleProviderRender(providerSelect.value,true);
        }
        return true;
      }
      function showCatalogUnavailable(){
        ['#homePopularGrid','#homeLatestGrid','#homeAllGrid','#allSlotGrid'].forEach(selector=>{
          const grid=document.querySelector(selector);if(!grid)return;
          const hasCards=grid.querySelector('.slot-card');if(hasCards)return;
          grid.replaceChildren();
          const empty=document.createElement('div');empty.className='catalog-empty';
          empty.textContent='Katalog game sedang disambungkan. Coba muat ulang beberapa saat lagi.';
          grid.appendChild(empty);
        });
        if(resultCount)resultCount.textContent='0 game';
      }
      async function requestProviderCatalog(){
        let lastError=null;
        for(let attempt=0;attempt<2;attempt++){
          const controller=typeof AbortController!=='undefined'?new AbortController():null;
          const timer=controller?setTimeout(()=>controller.abort(),8000):null;
          try{
            const response=await fetch(GAME_CATALOG_ENDPOINT,{headers:{Accept:'application/json'},cache:'no-store',credentials:'omit',redirect:'error',signal:controller?controller.signal:undefined});
            if(!response.ok)throw new Error('catalog_http_'+response.status);
            const payload=await response.json();
            if(!payload||payload.ok!==true||!Array.isArray(payload.games)||!payload.games.length)throw new Error('catalog_invalid_payload');
            if(timer)clearTimeout(timer);
            return payload;
          }catch(error){
            if(timer)clearTimeout(timer);lastError=error;
            if(attempt===0)await new Promise(resolve=>setTimeout(resolve,450));
          }
        }
        throw lastError||new Error('catalog_unavailable');
      }
      async function loadProviderCatalog(options={}){
        const force=options.force===true;
        if(catalogLoadPromise)return catalogLoadPromise;
        let restored=catalogGames.length>0;
        let restoredFromCurrent=false;
        if(!restored){
          const keys=[PUBLIC_GAME_CACHE_KEY].concat(LEGACY_GAME_CACHE_KEYS);
          for(const key of keys){
            const cached=readPublicCache(key);
            if(!cached)continue;
            if(applyProviderCatalogPayload(cached.value)){
              restored=true;
              restoredFromCurrent=key===PUBLIC_GAME_CACHE_KEY;
              // Current V76 cache may honor the short TTL. Legacy V74/V75 caches are
              // display fallbacks only and always trigger a background refresh.
              catalogCheckedAt=restoredFromCurrent?Date.now()-cached.age:0;
              break;
            }
          }
        }
        if(restored&&!force&&restoredFromCurrent&&Date.now()-catalogCheckedAt<PUBLIC_CACHE_TTL)return true;
        catalogLoadPromise=(async()=>{
          try{
            const payload=await requestProviderCatalog();
            if(applyProviderCatalogPayload(payload)){
              catalogCheckedAt=Date.now();
              writePublicCache(PUBLIC_GAME_CACHE_KEY,payload);
              return true;
            }
          }catch(_error){
            // Never erase a valid last-known catalog merely because Cloudflare/provider
            // refresh is temporarily slow. Existing cards remain usable while retrying.
            if(!restored)showCatalogUnavailable();
          }finally{
            catalogLoadPromise=null;
          }
          return restored;
        })();
        return catalogLoadPromise;
      }
      const GAME_LAUNCH_ENDPOINT=((window.BrandalbetConfig&&window.BrandalbetConfig.apiBase)||'https://brandalbet-backend.rkmpbajangda.workers.dev')+'/api/game-launch';
      function setGameLaunchState(open,title,message,providerName){
        const toggle=document.getElementById('game-info-toggle');
        const modal=document.getElementById('gameLaunchModal');
        const titleNode=document.getElementById('gameLaunchTitle');
        const messageNode=document.getElementById('gameLaunchMessage');
        const providerNode=document.getElementById('gameLaunchProvider');
        if(titleNode)titleNode.textContent=title||'Slot Game';
        if(messageNode)messageNode.textContent=message||'';
        if(providerNode)providerNode.textContent=providerName||'GOLDSLOTPALASE';
        if(toggle)toggle.checked=!!open;
        if(modal)modal.setAttribute('aria-hidden',open?'false':'true');
        document.body.classList.toggle('modal-open',!!open||document.querySelector('.ui-overlay.open')!==null||(document.getElementById('authModal')?.getAttribute('aria-hidden')==='false'));
      }
      function openGamePreview(card){
        if(!card)return;
        const play=document.getElementById('gamePreviewPlay');
        const art=document.getElementById('gamePreviewArt');
        const rtpFill=document.getElementById('gamePreviewRtpFill');
        const rtpValueNode=document.getElementById('gamePreviewRtpValue');
        const categoryNode=document.getElementById('gamePreviewCategory');
        const favorite=document.getElementById('gamePreviewFavorite');
        const name=sanitizeGameText(card.dataset.gameName||'Slot Game','Slot Game');
        const provider=sanitizeGameText(card.dataset.providerName||'GOLDSLOTPALASE','GOLDSLOTPALASE');
        const category=sanitizeGameText(card.dataset.category||'Slot Online','Slot Online');
        const image=String(card.dataset.image||'');
        const rtp=Number(card.dataset.rtp||0);
        if(play){
          play.dataset.providerId=String(card.dataset.providerId||'');
          play.dataset.gameSymbol=String(card.dataset.gameSymbol||'');
          play.dataset.gameName=name;
          play.dataset.providerName=provider;
        }
        if(art){
          art.innerHTML='';
          if(image){
            const img=document.createElement('img');img.src=image;img.alt=name;img.decoding='async';
            img.addEventListener('error',()=>{art.innerHTML='<div class="game-preview-empty">Gambar game tidak tersedia</div>';},{once:true});
            art.appendChild(img);
          }else art.innerHTML='<div class="game-preview-empty">Gambar game tidak tersedia</div>';
        }
        if(categoryNode)categoryNode.textContent=category;
        if(rtpFill){rtpFill.style.width=rtp>0?Math.max(0,Math.min(100,rtp))+'%':'0%';}
        const previewRtpLabel=document.querySelector('#gameLaunchModal .game-preview-rtp-label');
        if(previewRtpLabel)previewRtpLabel.textContent=card.dataset.rtpSimulated==='true'?'RTP · SIMULASI':'RTP';
        if(rtpValueNode)rtpValueNode.textContent=rtp>0?rtp.toFixed(2)+'%':'—';
        if(favorite){
          const matchingFav=card.querySelector('.card-fav');
          favorite.classList.toggle('is-fav',!!matchingFav&&matchingFav.classList.contains('is-fav'));
          favorite.textContent=favorite.classList.contains('is-fav')?'★ Favorit':'☆ Favorit';
          favorite.onclick=()=>{
            favorite.classList.toggle('is-fav');
            favorite.textContent=favorite.classList.contains('is-fav')?'★ Favorit':'☆ Favorit';
            if(matchingFav)matchingFav.classList.toggle('is-fav',favorite.classList.contains('is-fav'));
          };
        }
        setGameLaunchState(true,name,safeGameDescription({name,providerName:provider}),provider);
      }
      document.addEventListener('click',function(event){
        const fav=event.target&&event.target.closest?event.target.closest('.card-fav'):null;
        if(fav)return;
        const card=event.target&&event.target.closest?event.target.closest('.game-preview-trigger'):null;
        if(!card)return;
        event.preventDefault();
        openGamePreview(card);
      });
      document.addEventListener('keydown',function(event){
        if(event.key!=='Enter'&&event.key!==' ')return;
        const card=event.target&&event.target.closest?event.target.closest('.game-preview-trigger'):null;
        if(!card)return;
        event.preventDefault();openGamePreview(card);
      });

      function gameLaunchErrorMessage(code){
        const map={
          member_onboarding_required:'Lengkapi data pendaftaran member sebelum membuka game.',
          wallet_locked:'Wallet akun sedang terkunci. Hubungi administrator.',
          invalid_provider_id:'Provider game tidak valid. Muat ulang katalog.',
          invalid_game_symbol:'Kode game tidak valid. Muat ulang katalog.',
          provider_unconfigured:'Integrasi GoldslotPalase belum dikonfigurasi pada backend.',
          provider_unavailable:'Provider game sedang tidak dapat dihubungi. Coba lagi.',
          provider_invalid_launch_url:'Provider mengembalikan URL game yang tidak valid.',
          provider_http_error:'Server GoldslotPalase menolak permintaan launch. Coba lagi setelah katalog diperbarui.',
          provider_rejected:'Game ditolak oleh GoldslotPalase. Katalog akan diperbarui; pilih ulang game lalu coba lagi.',
          provider_invalid_response:'Respons GoldslotPalase tidak valid. Coba lagi beberapa saat.',
          game_launch_rate_limited:'Permintaan game yang sama masih diproses. Tunggu beberapa detik lalu coba lagi.',
          game_wallet_bridge_disabled:'Bridge saldo game belum diaktifkan pada backend.',
          game_wallet_scale_unverified:'Skala IDR provider belum diverifikasi pada backend.',
          game_wallet_transfer_pending:'Transfer saldo ke provider masih diproses. Coba lagi beberapa saat.',
          game_wallet_transfer_failed:'Transfer saldo ke provider gagal. Coba lagi atau hubungi administrator.',
          insufficient_game_balance:'Saldo game belum tersedia. Pastikan wallet member memiliki saldo.',
          auth_service_unconfigured:'Firebase Admin backend belum lengkap.',
          auth_service_unavailable:'Firebase Admin backend sedang bermasalah.',
          invalid_or_expired_id_token:'Sesi login sudah kedaluwarsa. Silakan masuk kembali.',
          member_session_required:'Sesi perangkat belum siap. Muat ulang halaman lalu coba kembali.',
          member_session_replaced:'Akun ini telah aktif pada perangkat lain. Silakan login kembali di perangkat ini.',
          origin_not_allowed:'Domain web member belum diizinkan oleh backend.',
          service_unavailable:'Layanan game sedang tidak tersedia.',
          game_launch_timeout:'Waktu membuka game terlalu lama. Coba kembali.',
          network_offline:'Perangkat sedang offline. Sambungkan internet lalu coba kembali.'
        };
        return map[String(code||'')]||'Game belum dapat dibuka. Silakan coba lagi.';
