      function createLaunchRequestId(){
        try{if(window.crypto&&typeof window.crypto.randomUUID==='function')return window.crypto.randomUUID();}catch(_e){}
        return 'launch-'+Date.now().toString(36)+'-'+Math.random().toString(36).slice(2,12);
      }
      async function launchCatalogGame(button){
        const master=window.BrandalMasterControl;
        if(master&&master.maintenanceMode===true){
          setGameLaunchState(true,button?.dataset?.gameName||'Game',master.maintenanceMessage||'Sistem sedang dalam pemeliharaan.',button?.dataset?.providerName||'');
          return;
        }
        if(master&&master.gameLaunchEnabled===false){
          setGameLaunchState(true,button?.dataset?.gameName||'Game','Game sementara dinonaktifkan oleh operator.',button?.dataset?.providerName||'');
          return;
        }
        const providerId=Number(button?.dataset?.providerId);
        const gameSymbol=String(button?.dataset?.gameSymbol||'').trim();
        const gameName=String(button?.dataset?.gameName||'Slot Game');
        const providerName=String(button?.dataset?.providerName||'GOLDSLOTPALASE');
        const launchRequestId=createLaunchRequestId();
        if(!Number.isSafeInteger(providerId)||providerId<=0||!gameSymbol){
          setGameLaunchState(true,gameName,'Data game belum siap. Muat ulang halaman agar katalog provider diperbarui.',providerName);
          return;
        }
        let current=null;
        try{current=window.firebase&&firebase.auth?firebase.auth().currentUser:null;}catch(_e){current=null;}
        if(!current){
          if(window.BrandalUI&&window.BrandalUI.openAuth)window.BrandalUI.openAuth('login');
          return;
        }

        button.disabled=true;
        button.setAttribute('aria-busy','true');
        setGameLaunchState(true,gameName,'Menyiapkan sesi game…',providerName);

        // Open synchronously from the user gesture to avoid mobile popup blockers.
        let popup=null;
        try{
          popup=window.open('about:blank','_blank');
          if(popup){
            try{popup.opener=null;}catch(_e){}
            try{
              popup.document.title='Brandalbet — Menyiapkan Game';
              popup.document.body.innerHTML='<div style="font-family:Arial,sans-serif;background:#03150e;color:#eafff1;min-height:100vh;display:grid;place-items:center;text-align:center;padding:24px"><div><b>Brandalbet</b><p style="opacity:.7">Menyiapkan game…</p></div></div>';
            }catch(_e){}
          }
        }catch(_e){popup=null;}

        const controller=typeof AbortController!=='undefined'?new AbortController():null;
        const timer=controller?setTimeout(()=>controller.abort(),18000):null;
        try{
          if(typeof navigator!=='undefined'&&navigator.onLine===false){
            const offline=new Error('network_offline');offline.code='network_offline';throw offline;
          }
          const makeAuthorization=(token)=>{
            if(window.BrandalDeviceSession&&window.BrandalDeviceSession.authorization){
              const value=window.BrandalDeviceSession.authorization(token);
              if(value&&value.includes('BrandalSession='))return value;
            }
            const err=new Error('member_session_required');err.code='member_session_required';throw err;
          };
          const performLaunch=async(forceRefresh,repairSession)=>{
            let token=await current.getIdToken(forceRefresh===true);
            let authorization='';
            try{authorization=makeAuthorization(token);}catch(authError){
              if(String(authError&&authError.code||authError&&authError.message||'')!=='member_session_required'||repairSession!==true)throw authError;
              if(!window.BrandalDeviceSession||!window.BrandalDeviceSession.claim)throw authError;
              await window.BrandalDeviceSession.claim(current,{replace:true});
              token=await current.getIdToken(true);
              authorization=makeAuthorization(token);
            }
            const options={
              method:'POST',
              headers:{Accept:'application/json','Content-Type':'application/json',Authorization:authorization},
              body:JSON.stringify({providerId,gameSymbol,launchRequestId}),
              cache:'no-store',
              credentials:'omit',
              redirect:'error'
            };
            if(controller)options.signal=controller.signal;
            let response;
            try{response=await fetch(GAME_LAUNCH_ENDPOINT,options)}catch(fetchError){
              if(fetchError&&fetchError.name==='AbortError'){const timeout=new Error('game_launch_timeout');timeout.code='game_launch_timeout';throw timeout}
              throw fetchError;
            }
            let payload={};
            try{payload=await response.json();}catch(_e){payload={};}
            return {response,payload};
          };
          let launchResult=await performLaunch(false,true);
          let launchCode=String(launchResult.payload&&launchResult.payload.error||'');
          if(launchResult.response.status===401&&launchCode==='member_session_required'){
            if(window.BrandalDeviceSession&&window.BrandalDeviceSession.claim)await window.BrandalDeviceSession.claim(current,{replace:true});
            launchResult=await performLaunch(true,false);
            launchCode=String(launchResult.payload&&launchResult.payload.error||'');
          }
          if(launchResult.response.status===401&&launchCode==='invalid_or_expired_id_token'){
            launchResult=await performLaunch(true,true);
          }
          const response=launchResult.response,payload=launchResult.payload;
          if(!response.ok||!payload||payload.ok!==true){
            const err=new Error(String(payload&&payload.error||'service_unavailable'));
            err.code=String(payload&&payload.error||'service_unavailable');
            err.status=response.status;
            throw err;
          }
          const raw=payload.game&&payload.game.launchUrl;
          let launchUrl;
          try{
            launchUrl=new URL(raw);
            if(launchUrl.protocol!=='https:'||launchUrl.username||launchUrl.password)throw new Error('unsafe');
          }catch(_e){
            const err=new Error('provider_invalid_launch_url');err.code='provider_invalid_launch_url';throw err;
          }
          setGameLaunchState(false,'','','');
          if(popup&&!popup.closed){
            try{popup.location.replace(launchUrl.toString());}
            catch(_e){try{window.location.assign(launchUrl.toString());}catch(_e2){window.location.href=launchUrl.toString();}}
          }else{
            try{window.location.assign(launchUrl.toString());}catch(_e){window.location.href=launchUrl.toString();}
          }
        }catch(error){
          try{if(popup&&!popup.closed)popup.close();}catch(_e){}
          const launchErrorCode=String(error&&error.code||error&&error.message||'');
          if(['provider_rejected','invalid_provider_id','invalid_game_symbol'].includes(launchErrorCode)){
            try{await loadProviderCatalog({force:true});}catch(_catalogError){}
          }
          setGameLaunchState(true,gameName,gameLaunchErrorMessage(launchErrorCode),providerName);
          if(['invalid_or_expired_id_token','member_session_replaced'].includes(launchErrorCode)){
            try{firebase.auth().signOut();}catch(_e){}
          }
        }finally{
          if(timer)clearTimeout(timer);
          button.disabled=false;
          button.removeAttribute('aria-busy');
        }
      }
      document.addEventListener('click',function(event){
        const button=event.target&&event.target.closest?event.target.closest('.game-launch-btn'):null;
        if(!button)return;
        event.preventDefault();
        if(event.stopImmediatePropagation)event.stopImmediatePropagation();
        launchCatalogGame(button);
      },true);

