      function openPromo(id){
        const item=PROMO_CONTENT[id];if(!item||!promoDetailModal)return;
        document.getElementById('promoModalBadge').textContent=item.badge;
        document.getElementById('promoModalTitle').textContent=item.title;
        document.getElementById('promoModalIntro').textContent=item.intro;
        const body=document.getElementById('promoModalBody');body.innerHTML='';
        const sections=item.sections?.length?item.sections:[['Keterangan Promo','Detail lengkap, periode, syarat, dan ketentuan mengikuti konfigurasi promo yang diterbitkan melalui backoffice.']];
        sections.forEach(([title,copy])=>{
