            const err=new Error(code);err.code=code;err.status=r.status;throw err;
          }
          if(!b||b.ok!==true){const err=new Error('invalid_server_response');err.code='invalid_server_response';throw err;}
          return b;
        }finally{clearTimeout(timer)}
      }
      const MIN_DEPOSIT_RUPIAH=20000;
      const MIN_WITHDRAW_RUPIAH=50000;
      function paymentNotice(id,message,success){
        const host=document.getElementById(id);
        if(!host)return;
        host.textContent=String(message||'');
        host.classList.toggle('show',Boolean(message));
        host.classList.toggle('success',Boolean(success));
      }
      function rupiahDigits(value){
        const digits=String(value??'').replace(/\D/g,'').replace(/^0+(?=\d)/,'');
        if(!digits)return 0;
        const number=Number(digits);
        return Number.isSafeInteger(number)&&number>=0?number:0;
      }
      function rupiahText(value){
        const amount=rupiahDigits(value);
        return amount?new Intl.NumberFormat('id-ID',{maximumFractionDigits:0}).format(amount):'';
      }
      function formatRupiahField(input){
        if(!input)return 0;
        const amount=rupiahDigits(input.value);
        input.value=amount?rupiahText(amount):'';
        return amount;
      }
      function updatePaymentSummaries(){
        const dep=rupiahDigits(document.getElementById('depositAmountInput')?.value);
        const wd=rupiahDigits(document.getElementById('withdrawAmountInput')?.value);
        const balance=Number(session?.wallet?.availableMinor||0);
        const depSummary=document.getElementById('depositSummaryAmount');
        if(depSummary)depSummary.textContent=money(dep);
        const wdBalance=document.getElementById('withdrawSummaryBalance');
        if(wdBalance)wdBalance.textContent=money(balance);
        const wdAmount=document.getElementById('withdrawSummaryAmount');
        if(wdAmount)wdAmount.textContent=money(wd);
        const wdRemaining=document.getElementById('withdrawSummaryRemaining');
        if(wdRemaining)wdRemaining.textContent=money(Math.max(0,balance-wd));
      }
      function selectAmountChip(chipSelector,inputId,clicked){
        const input=document.getElementById(inputId);
        if(!input||!clicked)return;
        const amount=Number(clicked.dataset.amount||0);
        if(!Number.isSafeInteger(amount)||amount<=0)return;
        input.value=rupiahText(amount);
        document.querySelectorAll(chipSelector).forEach(node=>node.classList.toggle('selected',node===clicked));
        updatePaymentSummaries();
        input.dispatchEvent(new Event('change',{bubbles:true}));
      }
      function syncAmountSelection(chipSelector,input){
        const amount=formatRupiahField(input);
        document.querySelectorAll(chipSelector).forEach(node=>{
          node.classList.toggle('selected',Number(node.dataset.amount||0)===amount&&amount>0);
        });
        updatePaymentSummaries();
      }
      const paymentReadinessCache=new Map();
      async function paymentEndpointReady(endpoint){
        if(!endpoint)return false;
        const key=String(endpoint);
        const cached=paymentReadinessCache.get(key);
        if(cached&&Date.now()-cached.time<60000)return cached.ready;
        try{
          const url=((window.BrandalbetConfig&&window.BrandalbetConfig.apiBase)||'')+key;
          const response=await fetch(url,{method:'OPTIONS',cache:'no-store'});
          const ready=response.ok||response.status===204||response.status===405;
          paymentReadinessCache.set(key,{ready,time:Date.now()});
          return ready;
        }catch(_error){
          paymentReadinessCache.set(key,{ready:false,time:Date.now()});
          return false;
        }
      }
      function paymentErrorText(error,type){
        const code=String(error?.code||error?.message||'');
        const common={
          payment_adapter_unavailable:'Payment gateway belum aktif.',
          payment_unavailable:'Payment gateway belum tersedia.',
          service_unavailable:'Layanan payment sedang tidak tersedia.',
          forbidden:'Akses transaksi ditolak.',
          invalid_or_expired_id_token:'Sesi login perlu diperbarui.',
          origin_not_allowed:'Akses transaksi dari domain ini belum diizinkan.'
        };
        if(common[code])return common[code];
        if(Number(error?.status||0)===404)return 'Payment gateway belum aktif.';
        return type==='deposit'?'Deposit belum dapat dibuat. Coba lagi setelah gateway aktif.':'Withdraw belum dapat diajukan. Coba lagi setelah gateway aktif.';
      }
      function renderDepositPaymentResult(payment){
        const host=document.getElementById('depositPaymentResult');
        if(!host)return;
        host.replaceChildren();
        if(!payment||typeof payment!=='object'){host.classList.remove('show');return;}
        const imageUrl=typeof payment.qrImageUrl==='string'?payment.qrImageUrl:'';
        if(imageUrl){
          try{
            const url=new URL(imageUrl);
            if(url.protocol==='https:'){
              const img=document.createElement('img');img.src=url.toString();img.alt='QRIS Deposit';img.loading='lazy';host.appendChild(img);
            }
          }catch(_e){}
        }
        const title=document.createElement('b');title.textContent='Deposit QRIS dibuat';
        const meta=document.createElement('small');
        meta.textContent=payment.reference?'Referensi: '+String(payment.reference):'Ikuti instruksi QRIS dari payment gateway.';
        host.append(title,meta);host.classList.add('show');
      }
      async function submitDeposit(){
        if(window.BrandalMasterControl&&window.BrandalMasterControl.memberWalletEnabled===false){paymentNotice('depositPaymentNotice','Layanan dompet sedang dinonaktifkan oleh operator.',false);return;}
        if(window.BrandalMasterControl&&window.BrandalMasterControl.maintenanceMode===true){paymentNotice('depositPaymentNotice',window.BrandalMasterControl.maintenanceMessage||'Sistem sedang dalam pemeliharaan.',false);return;}
        if(!memberReady())return;
        const input=document.getElementById('depositAmountInput');
        const button=document.getElementById('depositSubmitButton');
        const amount=rupiahDigits(input?.value);
        if(!Number.isSafeInteger(amount)||amount<=0){paymentNotice('depositPaymentNotice','Pilih atau masukkan nominal deposit terlebih dahulu.',false);return;}
        if(amount<MIN_DEPOSIT_RUPIAH){paymentNotice('depositPaymentNotice','Minimum deposit adalah Rp20.000.',false);return;}
        paymentNotice('depositPaymentNotice','',false);
        if(button){button.disabled=true;button.setAttribute('aria-busy','true');}
        try{
          const cfg=window.BrandalbetConfig?.payment||{};
          const endpoint=cfg.depositEndpoint||'/api/payment-deposit';
          if(!(await paymentEndpointReady(endpoint))){
            paymentNotice('depositPaymentNotice','Deposit QRIS sedang menunggu aktivasi payment gateway.',false);
            return;
          }
          const result=await api(endpoint,{
            method:'POST',
            body:JSON.stringify({amountRupiah:amount,channel:'QRIS'})
          });
          const payment=result.payment||result.deposit||result;
          renderDepositPaymentResult(payment);
          paymentNotice('depositPaymentNotice','Permintaan deposit QRIS berhasil dibuat.',true);
          const paymentUrl=payment&&typeof payment.paymentUrl==='string'?payment.paymentUrl:'';
          if(paymentUrl){
            try{const url=new URL(paymentUrl);if(url.protocol==='https:')window.location.assign(url.toString());}catch(_e){}
          }
        }catch(error){
          paymentNotice('depositPaymentNotice',paymentErrorText(error,'deposit'),false);
        }finally{
          if(button){button.disabled=false;button.removeAttribute('aria-busy');}
        }
      }
      async function submitWithdraw(){
        if(window.BrandalMasterControl&&window.BrandalMasterControl.memberWalletEnabled===false){paymentNotice('withdrawPaymentNotice','Layanan dompet sedang dinonaktifkan oleh operator.',false);return;}
        if(window.BrandalMasterControl&&window.BrandalMasterControl.maintenanceMode===true){paymentNotice('withdrawPaymentNotice',window.BrandalMasterControl.maintenanceMessage||'Sistem sedang dalam pemeliharaan.',false);return;}
        if(!memberReady())return;
        const input=document.getElementById('withdrawAmountInput');
        const passwordInput=document.getElementById('withdrawPasswordInput');
        const button=document.getElementById('withdrawSubmitButton');
        const amount=rupiahDigits(input?.value);
        const password=String(passwordInput?.value||'');
        const bank=session?.bankAccount||null;
        const available=Number(session?.wallet?.availableMinor||0);
        if(!Number.isSafeInteger(amount)||amount<=0){paymentNotice('withdrawPaymentNotice','Pilih atau masukkan nominal withdraw terlebih dahulu.',false);return;}
        if(amount<MIN_WITHDRAW_RUPIAH){paymentNotice('withdrawPaymentNotice','Minimum withdraw adalah Rp50.000.',false);return;}
        if(amount>available){paymentNotice('withdrawPaymentNotice','Nominal withdraw melebihi saldo tersedia.',false);return;}
        if(!bank){paymentNotice('withdrawPaymentNotice','Tambahkan rekening atau E-Wallet tujuan terlebih dahulu.',false);return;}
        if(password.length<6){paymentNotice('withdrawPaymentNotice','Masukkan password akun untuk mengonfirmasi Withdraw.',false);passwordInput?.focus();return;}
        paymentNotice('withdrawPaymentNotice','',false);
        if(button){button.disabled=true;button.setAttribute('aria-busy','true');}
        try{
          const cfg=window.BrandalbetConfig?.payment||{};
          const endpoint=cfg.withdrawEndpoint||'/api/payment-withdraw';
          if(!(await paymentEndpointReady(endpoint))){
            paymentNotice('withdrawPaymentNotice','Withdraw sedang menunggu aktivasi payment gateway.',false);
            return;
          }
          if(!user?.email||!window.firebase?.auth?.EmailAuthProvider)throw Object.assign(new Error('password_reauth_unavailable'),{code:'password_reauth_unavailable'});
          const credential=firebase.auth.EmailAuthProvider.credential(user.email,password);
          await user.reauthenticateWithCredential(credential);
          await user.getIdToken(true);
          const result=await api(endpoint,{
            method:'POST',
            body:JSON.stringify({amountRupiah:amount,destination:'saved_account'})
          });
          const request=result.withdraw||result.request||result;
          const ref=request&&request.reference?` Referensi: ${request.reference}.`:'';
          paymentNotice('withdrawPaymentNotice','Permintaan withdraw berhasil dikirim.'+ref,true);
          if(passwordInput)passwordInput.value='';
          await refresh({attempts:2,background:true});
        }catch(error){
          const code=String(error?.code||error?.message||'');
          if(code==='auth/wrong-password'||code==='auth/invalid-credential'||code==='auth/user-mismatch'){
            paymentNotice('withdrawPaymentNotice','Password akun tidak sesuai.',false);
          }else if(code==='auth/too-many-requests'){
            paymentNotice('withdrawPaymentNotice','Terlalu banyak percobaan. Coba kembali beberapa saat.',false);
          }else if(code==='password_reauth_unavailable'){
            paymentNotice('withdrawPaymentNotice','Verifikasi password belum tersedia untuk akun ini.',false);
          }else{
            paymentNotice('withdrawPaymentNotice',paymentErrorText(error,'withdraw'),false);
          }
        }finally{
          if(passwordInput)passwordInput.value='';
          if(button){button.disabled=false;button.removeAttribute('aria-busy');}
        }
      }
      document.addEventListener('click',(event)=>{
        const dep=event.target.closest?.('.deposit-amount-chip');
        if(dep){event.preventDefault();selectAmountChip('.deposit-amount-chip','depositAmountInput',dep);return;}
        const wd=event.target.closest?.('.withdraw-amount-chip');
        if(wd){event.preventDefault();selectAmountChip('.withdraw-amount-chip','withdrawAmountInput',wd);return;}
      });
      document.getElementById('depositAmountInput')?.addEventListener('input',(event)=>syncAmountSelection('.deposit-amount-chip',event.target));
      document.getElementById('withdrawAmountInput')?.addEventListener('input',(event)=>syncAmountSelection('.withdraw-amount-chip',event.target));
      document.getElementById('depositSubmitButton')?.addEventListener('click',submitDeposit);
      document.getElementById('withdrawSubmitButton')?.addEventListener('click',submitWithdraw);

      function render(){
        const ready=memberReady();
        const restoring=!!(user&&!ready&&(!sessionResolved||lastSessionError));
        document.body.classList.toggle('is-member',ready||restoring);
        document.body.classList.toggle('auth-restoring',restoring);
        const profile=session?.profile||{},wallet=session?.wallet||{},bank=session?.bankAccount||null;
        $('#topBalance').textContent=money(wallet.availableMinor||0);
        $('#walletBalance').textContent=money(wallet.availableMinor||0);
        const walletAmount=money(wallet.availableMinor||0);
        const walletState=wallet.status==='locked'?'Terkunci':ready?'Aktif':restoring?'Menyambung':'Memuat';
        const walletStatus=$('#walletStatus');if(walletStatus)walletStatus.textContent=walletState;
        const depositWalletBalance=$('#depositWalletBalance');if(depositWalletBalance)depositWalletBalance.textContent=walletAmount;
