        const depositWalletStatus=$('#depositWalletStatus');if(depositWalletStatus)depositWalletStatus.textContent=walletState;
        const withdrawWalletStatus=$('#withdrawWalletStatus');if(withdrawWalletStatus)withdrawWalletStatus.textContent=walletState;
        $('#profileName').textContent=profile.displayName||user?.displayName||(ready?'Member':'Guest');
