        const profileUsername=$('#profileUsername');if(profileUsername)profileUsername.textContent=profile.username?('@'+profile.username):'Member BrandalBet';
        const profileEditAvatar=$('#profileEditAvatar');if(profileEditAvatar)profileEditAvatar.textContent=avatarLetter;
        const profileEditName=$('#profileEditName');if(profileEditName)profileEditName.textContent=profile.displayName||user?.displayName||'Member';
        const profileEditEmail=$('#profileEditEmail');if(profileEditEmail)profileEditEmail.textContent=profile.email||user?.email||'—';
        const profileEditUsername=$('#profileEditUsername');if(profileEditUsername)profileEditUsername.textContent=profile.username?('@'+profile.username):'Member BrandalBet';
        const profileMiniBalance=$('#profileMiniBalance');if(profileMiniBalance)profileMiniBalance.textContent=walletAmount;
        const profileMiniBank=$('#profileMiniBank');if(profileMiniBank)profileMiniBank.textContent=bank?(bank.provider||'Aktif'):'Belum ada';
        const profileMiniSecurity=$('#profileMiniSecurity');if(profileMiniSecurity)profileMiniSecurity.textContent=user?.emailVerified?'Terverifikasi':'Aktif';
        const profileEmailStatus=$('#profileEmailStatus');if(profileEmailStatus)profileEmailStatus.textContent=user?.emailVerified?'Email Terverifikasi':'Email Aktif';
        $('#securityEmail').textContent=user?.email||'—';
        const securityEmailBadge=$('#securityEmailBadge');if(securityEmailBadge){securityEmailBadge.textContent=user?.emailVerified?'Terverifikasi':'Belum Verifikasi';securityEmailBadge.classList.toggle('ok',Boolean(user?.emailVerified));}
        const securitySessionStatus=$('#securitySessionStatus');if(securitySessionStatus)securitySessionStatus.textContent=ready?'Aktif':restoring?'Menyambung':'Tidak Aktif';
        $('#displayName').value=profile.displayName||'';
        $('#phone').value=profile.phone||'';
        $('#language').value=profile.language||'id';
        const settingsLanguage=$('#settingsLanguage');if(settingsLanguage)settingsLanguage.value=profile.language||'id';
        const saved=$('#bankSavedCard');if(saved)saved.hidden=!bank;
        const bankEmptyState=$('#bankEmptyState');if(bankEmptyState)bankEmptyState.style.display=bank?'none':'flex';
        if(bank){
          $('#bankSavedProvider').textContent=(bank.provider||'Rekening');
          $('#bankSavedNumber').textContent=bank.maskedAccountNumber||('•••• '+(bank.last4||''));
          $('#bankSavedName').textContent=bank.accountName||'';
          const bankSavedType=$('#bankSavedType');if(bankSavedType)bankSavedType.textContent=bank.type==='ewallet'?'E-Wallet':'Bank';
          const type=$('#bankType');if(type)type.value=bank.type||'bank';
          const name=$('#bankAccountName');if(name&&!name.value)name.value=bank.accountName||'';
          populateBankProviders(bank.type||'bank',bank.provider||'');
        }else populateBankProviders($('#bankType')?.value||'bank');
        const withdraw=$('#withdrawBankSelect');if(withdraw){withdraw.replaceChildren();const option=document.createElement('option');option.textContent=bank?`${bank.provider} · ${bank.maskedAccountNumber||bank.last4||''}`:'Belum ada rekening tersimpan';option.value=bank?.provider||'';withdraw.appendChild(option);withdraw.disabled=!bank;}
        const withdrawBankHeadline=$('#withdrawBankHeadline'),withdrawBankSubline=$('#withdrawBankSubline');
        if(withdrawBankHeadline)withdrawBankHeadline.textContent=bank?(bank.provider||'Rekening aktif'):'Belum ada rekening aktif';
        if(withdrawBankSubline)withdrawBankSubline.textContent=bank?`${bank.maskedAccountNumber||('•••• '+(bank.last4||''))} · ${bank.accountName||'Akun member'}`:'Tambahkan rekening terlebih dahulu agar withdraw dapat diproses.';
        const withdrawBankTypeLine=$('#withdrawBankTypeLine');if(withdrawBankTypeLine)withdrawBankTypeLine.textContent=bank?(bank.type==='ewallet'?'E-Wallet aktif':'Rekening bank aktif'):'Bank / E-Wallet';
        updatePaymentSummaries();
        const walletBankProvider=$('#walletBankProvider'),walletBankNumber=$('#walletBankNumber'),walletBankName=$('#walletBankName'),walletBankBadge=$('#walletBankBadge');
        if(walletBankProvider)walletBankProvider.textContent=bank?(bank.provider||'Rekening'):'Belum ada rekening';
        if(walletBankNumber)walletBankNumber.textContent=bank?(bank.maskedAccountNumber||('•••• '+(bank.last4||''))):'Tambahkan rekening untuk withdraw';
        if(walletBankName)walletBankName.textContent=bank?(bank.accountName||((bank.type==='ewallet'?'E-Wallet':'Bank')+' member')):'Bank / E-Wallet';
        if(walletBankBadge)walletBankBadge.textContent=bank?'Aktif':'Atur';
      }
      function renderWalletRecentRows(host,items){
        if(!host)return;
        host.replaceChildren();
        const list=Array.isArray(items)?items.slice(0,3):[];
        if(!list.length){const empty=document.createElement('div');empty.className='wallet-empty';empty.textContent='Belum ada transaksi untuk ditampilkan.';host.appendChild(empty);return;}
        list.forEach(item=>{
          const debit=item.type==='debit';
          const row=document.createElement('div');row.className='wallet-recent-row';
          const icon=document.createElement('span');icon.className='wallet-recent-ico'+(debit?' debit':'');icon.textContent=debit?'↑':'↓';
          const copy=document.createElement('div');copy.className='wallet-recent-copy';
          const title=document.createElement('b');title.textContent=debit?'Debit':'Kredit';
          const meta=document.createElement('small');
          meta.textContent=item.createdAt?new Intl.DateTimeFormat('id-ID',{dateStyle:'medium',timeStyle:'short'}).format(new Date(item.createdAt)):'Waktu tidak tersedia';
          copy.append(title,meta);
          const amount=document.createElement('span');amount.className='wallet-recent-amount'+(debit?' debit':'');amount.textContent=(debit?'−':'+')+money(item.amountMinor||0);
          row.append(icon,copy,amount);host.appendChild(row);
        });
      }
      async function loadWalletRecentTransactions(){
        if(!memberReady())return;
        const host=$('#walletRecentTransactions');if(!host)return;
        const revision=++walletRecentLoadRevision;
        host.replaceChildren();
        const loading=document.createElement('div');loading.className='wallet-empty';loading.textContent='Memuat transaksi terbaru…';host.appendChild(loading);
        try{
          const result=await api('/api/transactions');if(revision!==walletRecentLoadRevision)return;
          renderWalletRecentRows(host,Array.isArray(result.transactions)?result.transactions:[]);
        }catch(error){
          if(revision!==walletRecentLoadRevision)return;
          host.replaceChildren();const empty=document.createElement('div');empty.className='wallet-empty';empty.textContent='Riwayat transaksi belum tersedia.';host.appendChild(empty);
        }
      }
      function transactionDateText(value){
        if(!value)return 'Waktu tidak tersedia';
        const date=new Date(value);
        if(Number.isNaN(date.getTime()))return 'Waktu tidak tersedia';
        return new Intl.DateTimeFormat('id-ID',{dateStyle:'medium',timeStyle:'short'}).format(date);
      }
      function renderTransactionHistory(){
        const host=$('#transactionList'),count=$('#transactionCount');
        if(!host)return;
        const filtered=transactionFilter==='all'?transactionCache:transactionCache.filter(item=>item.type===transactionFilter);
        if(count)count.textContent=`${filtered.length} transaksi`;
        document.querySelectorAll('.transaction-filter-btn').forEach(btn=>btn.classList.toggle('active',btn.dataset.transactionFilter===transactionFilter));
        host.replaceChildren();
        if(!filtered.length){
          const empty=document.createElement('div');empty.className='transaction-empty';
          empty.textContent=transactionCache.length?'Tidak ada transaksi pada filter ini.':'Belum ada transaksi untuk ditampilkan.';
          host.appendChild(empty);return;
        }
        filtered.forEach(item=>{
          const debit=item.type==='debit';
          const row=document.createElement('div');row.className='transaction-modern-row';
          const icon=document.createElement('span');icon.className='transaction-modern-icon'+(debit?' debit':'');icon.textContent=debit?'↑':'↓';
          const copy=document.createElement('div');copy.className='transaction-modern-copy';
          const title=document.createElement('b');title.textContent=debit?'Debit Wallet':'Kredit Wallet';
          const meta=document.createElement('small');meta.textContent=transactionDateText(item.createdAt);
          copy.append(title,meta);
          const amount=document.createElement('div');amount.className='transaction-modern-amount';
          const value=document.createElement('b');value.className=debit?'debit':'';value.textContent=(debit?'−':'+')+money(item.amountMinor||0);
          const balance=document.createElement('small');balance.textContent=Number.isSafeInteger(item.balanceAfterMinor)?`Saldo ${money(item.balanceAfterMinor)}`:'';
          amount.append(value,balance);row.append(icon,copy,amount);host.appendChild(row);
        });
