      async function loadTransactions(){
        if(!memberReady())return;
        const host=$('#transactionList'),noticeHost=$('#transactionNotice');if(!host)return;
        const revision=++transactionLoadRevision;
        host.replaceChildren();
        const loading=document.createElement('div');loading.className='transaction-empty';loading.textContent='Memuat riwayat transaksi…';host.appendChild(loading);
        if(noticeHost)noticeHost.replaceChildren();
        try{
          const result=await api('/api/transactions');if(revision!==transactionLoadRevision)return;
          transactionCache=Array.isArray(result.transactions)?result.transactions:[];
          renderTransactionHistory();
        }catch(error){
          if(revision!==transactionLoadRevision)return;
          transactionCache=[];
          host.replaceChildren();
          const empty=document.createElement('div');empty.className='transaction-empty';empty.textContent='Riwayat transaksi belum tersedia. Coba lagi beberapa saat.';
          host.appendChild(empty);
          const count=$('#transactionCount');if(count)count.textContent='0 transaksi';
        }
      }
      const sleep=(ms)=>new Promise(resolve=>setTimeout(resolve,ms));
      function clearRestoreRetry(){
        if(restoreRetryTimer){clearTimeout(restoreRetryTimer);restoreRetryTimer=null;}
      }
      function scheduleRestoreRetry(){
        clearRestoreRetry();
        if(!user||memberReady())return;
        const delay=restoreBackoffMs;
        restoreBackoffMs=Math.min(restoreBackoffMs*2,60000);
        restoreRetryTimer=setTimeout(()=>{
          if(user&&!memberReady())refresh({attempts:2,background:true});
        },delay);
      }
      function terminalSessionError(error){
        const status=Number(error?.status||0);
        const code=String(error?.code||error?.message||'');
        return status===403||code==='origin_not_allowed';
      }
      async function refresh(options={}){
        const attempts=Math.max(1,Number(options.attempts||3));
        if(!user){
          clearRestoreRetry();restoreBackoffMs=15000;
          session=null;sessionResolved=true;lastSessionError=null;render();guardProtectedRoute();
          return false;
        }
        const owner=user,revision=sessionRevision;
        sessionResolved=false;lastSessionError=null;render();
        let lastError=null;
        for(let attempt=0;attempt<attempts;attempt++){
          if(revision!==sessionRevision||user!==owner)return false;
          try{
            if(attempt>0){
              try{await owner.getIdToken(true);}catch(_tokenError){}
            }
            const result=await api('/api/member-session');
            if(revision!==sessionRevision||user!==owner)return false;
            session=result;lastSessionError=null;sessionResolved=true;
            clearRestoreRetry();restoreBackoffMs=15000;
            render();guardProtectedRoute();
            if(selectedRoute()==='wallet'&&memberReady())loadWalletRecentTransactions();
            return memberReady();
          }catch(error){
            if(revision!==sessionRevision||user!==owner)return false;
            lastError=error;
            if(terminalSessionError(error))break;
            if(attempt+1<attempts)await sleep(350*Math.pow(2,attempt));
          }
        }
        if(revision!==sessionRevision||user!==owner)return false;
        session=null;lastSessionError=lastError;sessionResolved=true;
        render();guardProtectedRoute();scheduleRestoreRetry();
        return false;
      }
      function acceptVerifiedSession(firebaseUser,data){
        if(!firebaseUser||!data||!data.profile||data.profile.onboardingCompleted!==true)return false;
        if(auth&&auth.currentUser&&auth.currentUser.uid!==firebaseUser.uid)return false;
        sessionRevision++;
        clearRestoreRetry();restoreBackoffMs=15000;
        user=firebaseUser;session=data;sessionResolved=true;lastSessionError=null;
        render();guardProtectedRoute();
        return true;
      }
      window.BrandalMemberSession={
        accept:acceptVerifiedSession,
        refresh:refresh,
        lastError:function(){return lastSessionError;}
      };
      try{
        if(window.firebase){
