        type:text(byId('registerPaymentTypeModal').value),
        provider:text(byId('registerPaymentProviderModal').value),
        accountNumber:digits(byId('registerAccountNumberModal').value),
        accountName:text(byId('registerAccountNameModal').value)
      }
    };}
    function completeOnboarding(user){return backendRequest(user,'/api/member-onboarding',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(onboardingPayload())});}
    function closeAuth(){if(window.BrandalUI&&window.BrandalUI.closeAuth)return window.BrandalUI.closeAuth();var n=byId('auth-none');if(n)n.checked=true;var modal=byId('authModal');if(modal)modal.setAttribute('aria-hidden','true');document.body.classList.remove('modal-open');}
    function setBusy(btn,busy){if(!btn)return;btn.disabled=!!busy;if(busy)btn.setAttribute('aria-busy','true');else btn.removeAttribute('aria-busy');}
    function acceptSession(user,data){
      try{
        if(window.BrandalMemberSession&&window.BrandalMemberSession.accept)return window.BrandalMemberSession.accept(user,data);
      }catch(_e){}
      return true;
    }
    function prepareRegistrationRecovery(user,message){
      var em=byId('registerEmailModal');
      if(em&&user&&user.email){em.value=user.email;em.readOnly=true;em.setAttribute('data-auth-recovery','1');}
      if(window.BrandalUI&&window.BrandalUI.openAuth)window.BrandalUI.openAuth('register');
      if(window.BrandalInteraction&&window.BrandalInteraction.setStep)window.BrandalInteraction.setStep(1);
      showNotice('registerNoticeModal',message||'Akun Firebase ditemukan. Lengkapi data pendaftaran untuk mengaktifkan akun member.',false);
    }
    function clearRegistrationRecovery(){
      var em=byId('registerEmailModal');
      if(em){em.readOnly=false;em.removeAttribute('data-auth-recovery');}
    }
    function login(e){
      cancel(e);
      var em=byId('loginEmailModal'),pw=byId('loginPasswordModal'),btn=byId('authLoginSubmit');
      var signedUser=null;
      showNotice('loginNoticeModal','',false);
      if(!em||!em.checkValidity()){if(em)em.reportValidity();return false;}
      if(!pw||pw.value.length<6){if(pw)pw.reportValidity();return false;}
      setBusy(btn,true);beginInteractive();
      waitAuth().then(function(a){
        return a.signInWithEmailAndPassword(text(em.value),pw.value).then(function(credential){
          signedUser=credential&&credential.user?credential.user:a.currentUser;
          return claimDeviceSession(signedUser,true)
            .then(function(){return loadSessionWithRetry(signedUser,5);})
            .then(function(data){if(!acceptSession(signedUser,data)){var e=new Error('invalid_server_response');e.code='invalid_server_response';throw e;}return {auth:a,user:signedUser,data:data};});
        });
      }).then(function(ctx){
        clearRegistrationRecovery();
        var h=byId('route-home');if(h)h.checked=true;
        closeAuth();window.scrollTo(0,0);
      }).catch(function(err){
        var code=String(err&&err.code||err&&err.message||'');
        if(code.indexOf('onboarding_incomplete')>=0&&signedUser){
          prepareRegistrationRecovery(signedUser,'Login Firebase berhasil. Data member belum lengkap. Lengkapi data akun dan rekening di bawah ini lalu tekan Buat Akun.');
          return;
        }
        if(signedUser){
          showNotice('loginNoticeModal',mapError(err,'login'),false);
          try{window.BrandalDeviceSession&&window.BrandalDeviceSession.clear&&window.BrandalDeviceSession.clear();}catch(_e){}
          try{if(window.firebase&&firebase.auth)firebase.auth().signOut();}catch(_e2){}
          return;
        }
        showNotice('loginNoticeModal',mapError(err,'login'),false);
      }).then(function(){endInteractive();if(pw)pw.value='';setBusy(btn,false);},function(){endInteractive();if(pw)pw.value='';setBusy(btn,false);});
      return false;
    }
    function register(e){
      cancel(e);
      if(window.BrandalMasterControl&&window.BrandalMasterControl.maintenanceMode===true){showNotice('registerNoticeModal',window.BrandalMasterControl.maintenanceMessage||'Sistem sedang dalam pemeliharaan.',false);return false;}
      if(window.BrandalMasterControl&&window.BrandalMasterControl.registrationEnabled===false){showNotice('registerNoticeModal','Pendaftaran member sedang ditutup oleh operator.',false);return false;}
      var inter=window.BrandalInteraction,btn=byId('authRegisterSubmit');
      if(!inter||!inter.validateAccount()){if(inter)inter.setStep(1);return false;}
      if(!validateBank()){if(inter)inter.setStep(2);return false;}
      setBusy(btn,true);beginInteractive();showNotice('registerNoticeModal','',false);
      var created=null,aRef=null,registrationStage='firebase',reusedExisting=false;
      var requestedEmail=text(byId('registerEmailModal').value).toLowerCase();
      waitAuth().then(function(a){
        aRef=a;
        var current=a.currentUser;
        if(current&&String(current.email||'').toLowerCase()===requestedEmail){
          created=current;reusedExisting=true;return current;
        }
        function createFresh(){
          return a.createUserWithEmailAndPassword(requestedEmail,byId('registerPasswordModal').value)
            .then(function(credential){return credential&&credential.user?credential.user:a.currentUser;});
        }
        if(current)return a.signOut().then(createFresh);
        return createFresh();
      }).then(function(user){
        created=user;
        registrationStage='profile';var full=text(byId('registerFullNameModal').value);
        if(created&&full&&created.updateProfile)return created.updateProfile({displayName:full}).then(function(){return created;});
        return created;
      }).then(function(user){
        registrationStage='device-session';
        return claimDeviceSession(user,true).then(function(){return user;});
      }).then(function(user){
        registrationStage='onboarding';
        return completeOnboarding(user).then(function(){return user;});
      }).then(function(user){
        registrationStage='session';
        return loadSessionWithRetry(user,5).then(function(data){if(!acceptSession(user,data)){var e=new Error('invalid_server_response');e.code='invalid_server_response';throw e;}return data;});
      }).then(function(){
        clearRegistrationRecovery();
        showNotice('registerNoticeModal',reusedExisting?'Data member berhasil dilengkapi. Anda sudah masuk sebagai member.':'Akun berhasil dibuat. Anda sudah masuk sebagai member.',true);
        var h=byId('route-home');if(h)h.checked=true;
        setTimeout(closeAuth,250);window.scrollTo(0,0);
      }).catch(function(err){
        if(err)err.registrationStage=registrationStage;
        var base=mapError(err,'register');
        if(created&&registrationStage==='session'){
          showNotice('registerNoticeModal',base+' Data member sudah tersimpan, tetapi sesi member belum terverifikasi. Sistem akan mencoba menyambungkan ulang.',false);
          try{window.BrandalMemberSession&&window.BrandalMemberSession.refresh&&window.BrandalMemberSession.refresh({attempts:5,background:true});}catch(_e){}
          return;
        }
        if(created){
          prepareRegistrationRecovery(created,base+' Akun Firebase sudah aktif. Data yang belum tersimpan dapat dicoba lagi tanpa membuat akun baru.');
        }else{
          showNotice('registerNoticeModal',base,false);
        }
      }).then(function(){endInteractive();setBusy(btn,false);},function(){endInteractive();setBusy(btn,false);});
      return false;
    }
    function forgot(e){
      cancel(e);var em=byId('forgotEmailModal'),btn=byId('authForgotSubmit');showNotice('forgotNoticeModal','',false);
      if(!em||!em.checkValidity()){if(em)em.reportValidity();return false;}
      setBusy(btn,true);
      waitAuth().then(function(a){return a.sendPasswordResetEmail(text(em.value));})
      .then(function(){showNotice('forgotNoticeModal','Link reset password telah dikirim.',true);})
      .catch(function(err){showNotice('forgotNoticeModal',mapError(err,'forgot'),false);})
      .then(function(){setBusy(btn,false);},function(){setBusy(btn,false);});
      return false;
    }
    function onSubmit(e){var f=e.target;if(!f)return;if(f.id==='loginFormModal'){login(e);return;}if(f.id==='registerFormModal'){register(e);return;}if(f.id==='forgotFormModal'){forgot(e);return;}}
    document.addEventListener('submit',onSubmit,true);
    window.BrandalAuth={login:login,register:register,forgot:forgot,validateBank:validateBank,loadSession:loadSession};
    document.documentElement.setAttribute('data-brandal-auth-controller','v75');
    document.documentElement.setAttribute('data-brandal-release','V76_1_STABLE_CLOUDFLARE');
  })();
  //

