(function(){
  'use strict';
  const root=document.getElementById('homeBannerSlider');
  if(!root)return;
  const viewport=root.querySelector('.hero-viewport');
  const slides=Array.from(root.querySelectorAll('.hero-slide'));
  const images=slides.map(slide=>slide.querySelector('img'));
  const dots=Array.from(root.querySelectorAll('.hero-dot'));
  const message=root.querySelector('.hero-message');
  const home=document.getElementById('route-home');
  const motion=window.matchMedia?window.matchMedia('(prefers-reduced-motion: reduce)'):null;
  let index=0,timer=0,animationTimer=0,requested=null,hovered=false,focused=false;
  let paused=!!(motion&&motion.matches),pointer=null;
  const ready=img=>img.complete&&img.naturalWidth>0;
  function warm(i){images[i].loading='eager';}
  function allowed(){return !paused&&!hovered&&!focused&&!document.hidden&&home.checked;}
  function stop(){clearTimeout(timer);timer=0;}
  function schedule(){
    stop();
    if(allowed())timer=setTimeout(()=>{if(requested)schedule();else go((index+1)%slides.length,1);},5000);
  }
  function finish(){
    clearTimeout(animationTimer);
    slides.forEach((slide,i)=>{
      slide.hidden=i!==index;
      slide.setAttribute('aria-hidden',String(i!==index));
      slide.style.transition='none';slide.style.transform='translateX(0)';
    });
  }
  function sync(){
    dots.forEach((dot,i)=>dot.setAttribute('aria-current',String(i===index)));
    root.dataset.activeBanner=String(index+1);
  }
  function go(target,direction){
    target=(target+slides.length)%slides.length;
    stop();
    if(target===index){requested=null;schedule();return;}
    warm(target);
    // Keep the current image visible while the next image downloads.
    if(!ready(images[target])){requested={target,direction};schedule();return;}
    requested=null;finish();
    const old=slides[index],next=slides[target];
    next.hidden=false;next.style.transform='translateX('+(-direction*100)+'%)';
    void next.offsetWidth;
    next.style.transition='';old.style.transition='';
    next.style.transform='translateX(0)';old.style.transform='translateX('+(direction*100)+'%)';
    old.setAttribute('aria-hidden','true');next.setAttribute('aria-hidden','false');
    index=target;message.hidden=true;sync();
    animationTimer=setTimeout(finish,motion&&motion.matches?0:450);
    warm((index+1)%slides.length);schedule();
  }
  images.forEach((img,i)=>{
    img.addEventListener('load',()=>{
      if(i===0&&img.naturalWidth&&img.naturalHeight)viewport.style.aspectRatio=img.naturalWidth+'/'+img.naturalHeight;
      if(i===index)message.hidden=true;
      if(requested&&requested.target===i&&home.checked&&!document.hidden)go(i,requested.direction);
    });
    img.addEventListener('error',()=>{
      if(i===index)message.hidden=false;
      if(requested&&requested.target===i){requested=null;schedule();}
    });
  });
  if(ready(images[0]))viewport.style.aspectRatio=images[0].naturalWidth+'/'+images[0].naturalHeight;
  dots.forEach((dot,i)=>dot.addEventListener('click',()=>go(i,1)));
  root.addEventListener('keydown',event=>{
    if(event.key==='ArrowRight'||event.key==='ArrowLeft'){
      event.preventDefault();const direction=event.key==='ArrowRight'?1:-1;go(index+direction,direction);
    }
  });
  viewport.addEventListener('pointerdown',event=>{
    if(event.isPrimary===false||event.button>0)return;
    pointer={id:event.pointerId,x:event.clientX,y:event.clientY};stop();
    if(viewport.setPointerCapture)viewport.setPointerCapture(event.pointerId);
  });
  viewport.addEventListener('pointerup',event=>{
    if(!pointer||pointer.id!==event.pointerId)return;
    const dx=event.clientX-pointer.x,dy=event.clientY-pointer.y;pointer=null;
    if(Math.abs(dx)>35&&Math.abs(dx)>Math.abs(dy)*1.3)go(index+(dx>0?1:-1),dx>0?1:-1);
    else schedule();
  });
  viewport.addEventListener('pointercancel',()=>{pointer=null;schedule();});
  root.addEventListener('pointerenter',event=>{if(event.pointerType==='mouse'){hovered=true;stop();}});
  root.addEventListener('pointerleave',()=>{hovered=false;schedule();});
  root.addEventListener('focusin',()=>{focused=true;stop();});
  root.addEventListener('focusout',event=>{focused=root.contains(event.relatedTarget);schedule();});
  document.addEventListener('visibilitychange',()=>{if(document.hidden){requested=null;stop();}else schedule();});
  document.querySelectorAll('.route-radio').forEach(route=>route.addEventListener('change',()=>{
    if(!home.checked)requested=null;schedule();
  }));
  window.addEventListener('pagehide',()=>{requested=null;stop();finish();});
  window.addEventListener('pageshow',schedule);
  if(motion&&motion.addEventListener)motion.addEventListener('change',event=>{paused=event.matches;sync();schedule();});
  sync();warm(1);schedule();
})();
